quests[42165] = { id = 42165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exemplare aus Azsuna" }
quests[42166] = { id = 42166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was geht hier vor?", description = "Wir wissen nicht viel über die Aktivitäten der Empyreumgesellschaft hier, aber mit Eurer Perle werdet Ihr wie <ein neuer Rekrut/eine neue Rekrutin> aussehen. So könnt Ihr hoffentlich ein paar Fragen stellen und nach dieser seltsamen Magie Ausschau halten, die Erzmagier Vargoth entdeckt hat.\n\nWir treffen uns dann später am Rundbau auf dem Hügel.", sourceObjective = "Befragt 5 Mitglieder der Empyreumgesellschaft und erkundet ihr Gelände.", progress = "Was glaubt Ihr, was sie vorhaben?", completion = "Sie bedienen sich der Teufelsmagie. Ich wusste, dass irgendetwas mit ihnen nicht stimmt, aber so etwas habe ich nicht geahnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[42167] = { id = 42167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Gather Bit" }
quests[42168] = { id = 42168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick in die Finsternis", description = "<Freund/Freundin> ist nun bereit, das Ritual auszuführen!\n\nDenkt daran, <Freund/Freundin>, der Schädel muss überzeugt werden, dass es in seinem Sinne ist, sich in Eurem Besitz zu befinden. Wenn wir den Schädel zwingen müssen, Euch zu dienen, wird er deutlich schwächer sein.", sourceObjective = "Führt das Ritual aus, um mit dem Schädel der Man'ari zu kommunizieren, und überzeugt ihn, seinen Standort preiszugeben.", progress = "Der Ritualkreis ist bereit, Freund.", completion = "Ja, die Teufelsseelenbastion! Calydus weiß, wo sie liegt!\n\nCalydus kann einen Pfad schaffen, der zu einem der dortigen Portale führt!", sourceObjectiveStatus = "unverified-source-field" }
quests[42169] = { id = 42169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totgeglaubt zurückgelassen" }
quests[42170] = { id = 42170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Traumweber", description = "Unterstützt die Druiden von Val'sharah, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests in Val'sharah ab.", completion = "Die Traumweber danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42171] = { id = 42171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzter Ausweg", description = "Die Empyreumgesellschaft zählt jetzt ganz sicher einige Mitglieder weniger. Für eine Weile werden sie wohl nicht mehr versuchen, neue Mitglieder zu rekrutieren.\n\nEs gibt nur noch einen Ort, den wir noch nicht untersucht haben, und ich vermute, dass die Rune, die wir gefunden haben, diese Tür öffnen kann. Lasst uns nachsehen, was sich in dem Gebäude befindet.", sourceObjective = "Verwendet die Rune des Öffnens, um die Tür des Gebäudes der Empyreumgesellschaft zu öffnen.", progress = "Ich dachte, ich sehe mich mal ein bisschen um, bevor ich Euch am Rundbau treffe. Leider ist mein Unsichtbarkeitszauber zum denkbar ungünstigsten Zeitpunkt abgelaufen. Gut, dass Ihr mich gefunden habt! Was habt Ihr denn da entdeckt, {name}?", completion = "Ich danke Euch, dass Ihr die Wahrheit über die Empyreumgesellschaft ans Licht gebracht habt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[42172] = { id = 42172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leygrottenverseuchung" }
quests[42173] = { id = 42173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektrohappen" }
quests[42174] = { id = 42174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions von Elune" }
quests[42175] = { id = 42175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsende Macht", description = "Jetzt, wo Ihr noch mächtiger geworden seid, benötigt die Tirisgarde Eure Hilfe, {name}. Trefft mich in der Halle des Wächters, sobald Ihr Eure Abenteuer abgeschlossen habt.", sourceObjective = "Trefft Euch mit Meryl Teufelssturm in der Halle des Wächters.", completion = "Gut, Euch hier zu sehen, {name}. Es gibt noch viel zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[42176] = { id = 42176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skovald erhebt sich" }
quests[42177] = { id = 42177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Morheim" }
quests[42178] = { id = 42178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schockabsorbierer" }
quests[42182] = { id = 42182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Kampf!" }
quests[42183] = { id = 42183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Kampf!" }
quests[42184] = { id = 42184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Elementardiplomatie", description = "Der Herr der Gezeiten hat sich dem Irdenen Ring angeschlossen, aber wir müssen immer noch die übrigen Elementarlords vereinen.\n\nAls nächsten Schritt unserer Kampagne habe ich eine diplomatische Mission zum Himmelswall arrangiert.\n\nDas Ziel dieser Mission ist, nach der Niederlage des Windlords Al'Akir die aktuelle politische Lage am Himmelswall zu stabilisieren und alle Elementare ausfindig zu machen, die gewillt sind, uns zu unterstützen.\n\nIhr könnt sofort einen Anhänger mit dieser Mission beauftragen.", sourceObjective = "Schließt die Mission \"Elementardiplomatie\" erfolgreich ab.", completion = "Die zum Himmelswall entsandten Champions des Irdenen Rings sind erfolgreich zur Klassenordenshalle zurückgekehrt.\n\nDie Ebene der Luft befindet sich zurzeit in Aufruhr, aber unsere Champions haben einen mächtigen Elementar ausfindig gemacht, der vielleicht gewillt ist, uns zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42185] = { id = 42185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt niemals allein", description = "Prustaga ist mit einiger Sicherheit auf dem Weg zum Tempel der Stürme, wo ich Titanenblitz einst mit dem Donnerfunken erfüllt habe.\n\nWenn ich richtigliege, wird sie versuchen, die ersehnte gottgleiche Macht zu erlangen, indem sie den Prozess umkehrt und sich selbst mit dem Funken erfüllt!\n\nHoffentlich treibt Thorim sich nicht wieder mit seinen Kötern herum. Wenn die hiesigen Vrykul auf Prustagas Seite stehen, könnte die Situation... problematisch werden.", sourceObjective = "Sucht Thorim am Tempel der Stürme auf und beschafft Titanenblitz.", completion = "Brann wird mir kein Wort glauben, wenn ich ihm vom Geschehenen berichte. Was für ein Abenteuer!", sourceObjectiveStatus = "unverified-source-field" }
quests[42186] = { id = 42186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsende Macht", description = "Eisenkörper Ponshu wünscht, Euch zu sehen.\n\nUnsere Kampagne zur Verteidigung der Verheerten Inseln ist angelaufen und wir benötigen Eure Hilfe auf der Wandernden Insel.", sourceObjective = "Sprecht mit Eisenkörper Ponshu auf der Wandernden Insel.", completion = "Danke, dass Ihr gekommen seid, Großmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[42187] = { id = 42187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Wir sind immer noch dabei, uns vom Angriff auf den Gipfel der Ruhe zu erholen.\n\nUm uns beim Wiederaufbau des Ordens zu unterstützen, sollten wir die größten Champions unserer Klasse anheuern und an unserer Seite kämpfen lassen.\n\nIch weiß, dass Chen und Li Li Sturmbräu sich ohne zu zögern unserer Sache anschließen würden. Sprecht mit ihnen, um sie als Champions zu rekrutieren, und sprecht danach mit Meister Hsu.", sourceObjective = "Heuert Chen und Li Li Sturmbräu an und sprecht danach mit Meister Hsu.", completion = "Chen und Li Li zählen zu den herausragendsten Mönchen der jüngeren Vergangenheit.\n\nSolange sie sich von Ärger fernhalten, werden sie ein Aushängeschild unseres Ordens sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42188] = { id = 42188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobundo wartet", description = "Nobundo und die anderen Champions des Irdenen Rings haben sich unten versammelt. Sie warten auf Eure Ankunft, <Scharfseher/Scharfseherin>.\n\nEs steht ein mächtiges Ritual bevor und sie erwünschen Eure Anwesenheit. Macht Euch vorerst keine Sorgen um die Verwaltungsarbeit, ich kümmere mich hier um alles.\n\nNobundo erwartet Euch bereits. Mögen die Elemente mit Euch sein, <Scharfseher/Scharfseherin>.", sourceObjective = "Sprecht mit Nobundo im Herz von Azeroth.", completion = "Ich hörte, dass Ihr auf den Verheerten Inseln gute Fortschritte gemacht habt. Ausgezeichnet. Aber wir hier am Mahlstrom waren auch nicht müßig.\n\nAuf uns warten wichtige Dinge...", sourceObjectiveStatus = "unverified-source-field" }
quests[42189] = { id = 42189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Mage - Flavor Event 01" }
quests[42190] = { id = 42190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtierschützer" }
quests[42191] = { id = 42191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Dank Euch nimmt der Orden des Verheerten Tempels langsam wieder vernünftige Form an.\n\nAber es gibt noch viel zu tun. Als <unser Anführer/unsere Anführerin> könnt Ihr über die zukünftige Entwicklung unseres Ordens bestimmen.\n\nSprecht mit Jia Nummer Neun. Sie wird Euch über alles unterrichten.", sourceObjective = "Sprecht mit Jia Nummer Neun.", completion = "Exzellente Arbeit, {name}! Ich sehe, dass der Orden des Verheerten Tempels in guten Händen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[42192] = { id = 42192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Mage - Flavor Event 02" }
quests[42193] = { id = 42193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gjallarhorn", description = "Ihr habt Euch ein ums andere Mal als würdig erwiesen, {name}. Ihr seid ohne Zweifel <der/die> Richtige, um Odyns Armeen in der letzten Schlacht anzuführen.\n\nAber zunächst müsst Ihr das Gjallarhorn in Euren Besitz bringen, um damit unseren Verbündeten mitzuteilen, dass das Ende der Zeit naht.\n\nKönig Svergan Sturmmantel war der letzte lebende Hüter des Horns.\n\nSucht seinen Geist auf dem Feld der Gefallenen Könige in Sturmheim auf und fragt ihn nach dem Horn.", sourceObjective = "Sucht Svergan Sturmmantel.", completion = "Was habt Ihr hier zu suchen? Wollt Ihr auch Familienerbstücke plündern wie all die anderen?", sourceObjectiveStatus = "unverified-source-field" }
quests[42194] = { id = 42194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geraubte Ehre", description = "Es war meine Pflicht, das Gjallarhorn zu beschützen, {race}. Ich werde das Richtige tun, aber zuvor benötige ich Eure Hilfe.\n\nDie Mystiker meiner Zeit haben meiner Familie die Ehre abgesprochen und dieses Grab der Plünderung preisgegeben.\n\nIch kann keine Ruhe finden, solange sich die Familienerbstücke in den Händen der Diener des falschen Gottkönigs befinden.\n\nBringt sie mir zurück, dann werde ich Euch helfen, das Gjallarhorn zu finden!", sourceObjective = "Svergan Sturmmantel möchte, dass Ihr die Krone des Vergessenen Königs, das Sturmmantelsignet und das Medaillon des Drachenreiters im Runenwald besorgt.", progress = "Habt Ihr mir die Familienerbstücke zurückgebracht, {race}?", completion = "Odyn führt wahrlich Eure Hand, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42197] = { id = 42197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Fürst Hydraxis", sourceObjective = "Lord Neptulon hat mich geschickt, um den Irdenen Ring bei der Verteidigung Azeroths zu unterstützen.\n\nMir wurde befohlen, dem Scharfseher des Irdenen Rings mit der gleichen Loyalität zu dienen wie dem Herrn der Gezeiten. Ich werde diese Pflicht erfüllen, bis die Brennende Legion von dieser Welt vertrieben und die Zukunft von Azeroth gesichert wurde.\n\nIch erwarte Euren Befehl, Scharfseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[42198] = { id = 42198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Sturmruferin Mylra", sourceObjective = "Die Elemente zu vereinen, wird keine leichte Aufgabe werden, Scharfseher {name}.\n\nDas hier sind wahrhaft finstere Zeiten... Aber keine Sorge, wir werden sie gemeinsam durchstehen!\n\nDie gute Mylra hält Euch den Rücken frei, Scharfseher!\n\nUnd jetzt sollten wir uns auf den Weg machen! Wir haben keine Zeit zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[42200] = { id = 42200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Untersuchung von Tiefenheim", description = "Damit der Irdene Ring die vier Elementarlords als Verbündete im Kampf gegen die Brennende Legion gewinnen kann, müssen wir die Steinmutter Therazane davon überzeugen, sich uns anzuschließen.\n\nTherazane ist bis jetzt unseren Verhandlungen mit den Elementen ferngeblieben.\n\nEs gibt Gerüchte über eine neue Bedrohung, die innerhalb von Tiefenheim Gestalt annimmt. Wenn diese Gerüchte wahr sind, benötigt sie vielleicht unsere Hilfe.\n\nIch habe eine diplomatische Mission zur Klärung der Situation in Tiefenheim vorbereitet. Ihr könnt sofort einen Anhänger damit beauftragen.", sourceObjective = "Schließt die Mission \"Untersuchung von Tiefenheim\" erfolgreich ab.", completion = "Die Mission in Tiefenheim war ein Erfolg. Die Champions des Irdenen Rings haben Kontakt mit Therazane aufgenommen, aber die Situation ist noch prekärer, als wir befürchtet hatten...", sourceObjectiveStatus = "unverified-source-field" }
quests[42202] = { id = 42202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache, kalt serviert", description = "Mein Dorf wurde von einem Drogbarstamm ausgelöscht, der genau die Bestie anbetet, die Ihr sucht. Es wurde keiner verschont.\n\nHelft mir, mein Volk zu rächen, und ich werde Euch bei Eurer Suche nach Jorhuttam helfen.", sourceObjective = "Tötet Dorgrub den Grausamen, Ugrul Schädelspalter und 8 Drogbar der Frostklippen am Hochberggipfel.", completion = "Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42203] = { id = 42203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Bit" }
quests[42204] = { id = 42204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorhuttam", description = "Ihr habt Euren Teil der Abmachung erfüllt. Nun ist es an mir.\n\nNehmt diese Drogbartrommeln. Dann trommelt darauf, um Jorhuttam zu einem Festmahl herbeizurufen.\n\nSucht nach dem Futterhaufen des großen Wurms und lockt ihn mit den Trommeln an.", sourceObjective = "Benutzt die Frostklippentrommeln in der Nähe von Jorhuttams Futterhaufen und tötet Jorhuttam, um Euch das Gjallarhorn zu besorgen.", progress = "Das Gjallarhorn, {name}. Habt Ihr es endlich gefunden?", completion = "Es ist vollbracht! Die Armeen von Ulduar sind jetzt durch ihren Eid verpflichtet, sich uns anzuschließen, da sich das Gjallarhorn in unserem Besitz befindet!", sourceObjectiveStatus = "unverified-source-field" }
quests[42205] = { id = 42205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entrance Bit" }
quests[42206] = { id = 42206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung", description = "Die Empyreumgesellschaft ist auf jeden Fall viel gefährlicher, als sie erscheint. Kaum vorstellbar, dass Magier sich mit Teufelsmagie abgeben... Schlimm genug, dass Hexenmeister und die Legion damit experimentieren!\n\nDa sich unser Freund Ravandwyr verspätet zu haben scheint, werden wir uns selbst um die Sache kümmern müssen. Wir sollten diese Sekte ausmerzen, damit sie niemanden mehr in ihren schändlichen Bann ziehen kann.", sourceObjective = "Tötet 10 Mitglieder der Empyreumgesellschaft.", progress = "Glaubt Ihr, wir haben ihre Reihen genug geschwächt?", completion = "Ihr gefallt mir, {name}. Wenn es sein muss, versteht Ihr, entschlossen zu handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[42208] = { id = 42208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Feuerlande", description = "Es ist Zeit, in die Feuerlande zurückzukehren, <Scharfseher/Scharfseherin>. Ich muss Euch ja nicht sagen, wie gefährlich es dort ist.\n\nRagnaros ist zwar besiegt, aber die Elementare der Feuerlande setzen ihren Vernichtungsfeldzug fort. Unsere Anwesenheit dort werden sie sicher als Akt der Aggression empfinden.\n\nIch habe eine Aufklärungsmission in die Feuerlande vorbereitet. Wir sollten nur unsere besten Champions für diese Begegnung mit den Elementaren aussenden.\n\nWenn die Mission erfolgreich verläuft, erhalten wir vielleicht die benötigten Informationen, um die Feuerlande für unsere Sache zu gewinnen.", sourceObjective = "Schließt die Missionen \"Rückkehr in die Feuerlande\" ab.", completion = "Unsere Mission in den Feuerlanden scheint ein Erfolg gewesen zu sein, Scharfseher. Es gibt viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42209] = { id = 42209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung der Entführten" }
quests[42210] = { id = 42210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schriftrollen des Wissens", description = "Unsere Truppen sind bereit! Jetzt ist es an der Zeit, sie im Feld zu testen, und ich habe dafür die perfekte Aufgabe.\n\nJia Nummer Neun ist eine sehr respektierte Gelehrte. Sie verfügt über Wissen, das uns helfen kann, den Orden zu verbessern. Aber viele ihrer bedeutenden Schriftrollen wurden während des Angriffs auf den Gipfel der Ruhe zurückgelassen.\n\nSendet sofort unsere Champions aus, um diese Dokumente zurückzuholen!", sourceObjective = "Schließt die Mission \"Schriftrollen des Wissens\" ab.", progress = "Wie ist es gelaufen?", completion = "Es war ein glücklicher Umstand, dass wir diese Schriftrollen sichern konnten. Jia Nummer Neun wird für unseren Orden von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42211] = { id = 42211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leodraths Sippe" }
quests[42212] = { id = 42212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Mage - Flavor Event 03" }
quests[42213] = { id = 42213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Golganneths Gezeitenstein", description = "<Nachdem Ihr Königin Azsharas Zorn nun besiegt habt und den Gezeitenstein in Händen haltet, ist es an der Zeit, ihn in der Porträtgalerie der Kammer des Wächters in Dalaran zu platzieren.>", sourceObjective = "Verwendet den zentralen Teleporter in Dalaran und platziert Golganneths Gezeitenstein dann in in der Porträtgalerie der Kammer des Wächters.", completion = "<Erzmagier Khadgar hat hier einen Platz für Golganneths Gezeitenstein und den Rest der Säulen der Schöpfung reserviert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42214] = { id = 42214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschlechtsreife", description = "Da Ihr gerade so auf Murlocs konzentriert seid...\n\nViele Murlocs sind dafür bekannt, Schmuck zu tragen, um potenzielle Geschlechtspartner zu beeindrucken. Ich wette, dass wir ein paar von diesen Schmuckstücken verwenden können.\n\nSammelt einige davon ein und bringt sie mir. Je nasser, desto besser!", sourceObjective = "Sammelt 10 Salzaugenarmreife.", progress = "Ich kann mir gut vorstellen, dass Schmuck einen Murloc attraktiver machen könnte...", completion = "Oh ja! Das hier sind ein paar fantastische Schmuckstücke. Jetzt einfach nur noch den Schleim abkratzen und...", sourceObjectiveStatus = "unverified-source-field" }
quests[42220] = { id = 42220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffbrüchige Matrosen", description = "<Die Gilblin und Makrura von Mak'rana haben die Matrosen der Verlassenen aus dem nahen Schiffswrack gefangen genommen.>\n\n<Es sieht so aus, als würden die Matrosen vergiftet und anderweitig malträtiert werden. Es wäre das Beste, sie von ihren Qualen zu erlösen.>", sourceObjective = "Erlöst 10 Matrosen der Revanche der Königin von ihren Qualen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42221] = { id = 42221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Bitterbrine" }
quests[42222] = { id = 42222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht über die Empyreumgesellschaft", description = "Ich kann kaum glauben, dass sich Erzmagier Vargoth mit so einer widerwärtigen Gruppe eingelassen haben soll! Es muss einen guten Grund dafür geben, warum er da war...\n\nAuf jeden Fall sollten wir unverzüglich in die Halle des Wächters zurückkehren und Meryl erzählen, was wir hier herausgefunden haben.", sourceObjective = "Kehrt zur Halle des Wächters zurück.", completion = "Ravandwyr äußert sich sehr positiv darüber, wie Ihr Euch um die Sache mit der Empyreumgesellschaft gekümmert habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42223] = { id = 42223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erkundung des Purpurdickichts", description = "Wenn Ihr nach Osten reisen solltet, möchte ich Euch um einen Gefallen bitten.\n\nWährend wir das Lager aufschlugen, hat sich ein Mitglied der Karawane aufgemacht, um die Umgebung der Stadt zu erkunden. Lilryia Morgenwind hätte schon längst wieder da sein sollen.\n\nIch wäre Euch sehr dankbar, wenn Ihr Ausschau nach ihr halten könntet. Sie wollte die Ruinen des Morgenspalts erkunden.", sourceObjective = "Sucht nach Lilryia Morgenwind im Morgenspalt.", completion = "Der Zeitpunkt Eurer Ankunft ist perfekt, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42224] = { id = 42224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Mondschatten gehüllt", description = "Ich weiß nicht, was Theryn gefunden hat, aber ich weiß, wo er es gefunden hat.\n\nAm Mondschleiersanktum im Westen. Jenseits des Tempels von Fal'adora.\n\nWas auch immer Theryns arkane Essenz veränderte... Welche Kraft auch immer es war, mit deren Hilfe es Kel'danath gelang, einen besänftigenden Zauber für die Verdorrten zu wirken... Dort ist die Quelle.\n\nIch weiß es so sicher, als wäre ich selbst dort gewesen.", sourceObjective = "Erkundet das Mondschleiersanktum.", completion = "<Ihr erkennt das Relikt aus Thalyssras Vision.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42225] = { id = 42225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel brechen", description = "<Als Ihr das Relikt betrachtet, hört Ihr Thalyssras Stimme in Eurem Geist.>\n\nIhr habt es gefunden! Aber es wird durch Siegel geschützt.\n\nDurchsucht den Raum nach etwas, um diese Siegel zu brechen.", sourceObjective = "Brecht das Siegel der Gezeiten, das Siegel der Erde und das Siegel des Himmels.", completion = "<Als die magische Barriere schwindet, hört Ihr draußen das Rascheln von Blättern und das Klappern von Mandibeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42226] = { id = 42226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondschattenbastion", description = "<Das Hantieren mit dem Relikt hat ein paar garstige Kreaturen aus dem Untergrund von Falanaar herbeigelockt.>", sourceObjective = "Tötet einen Netzschleuderer der Fal'dorei, einen Brutrufer der Fal'dorei und einen Witwenmacher der Fal'dorei.", completion = "Habt Ihr eine Vorstellung davon, was Ihr getan habt?!", sourceObjectiveStatus = "unverified-source-field" }
quests[42227] = { id = 42227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in den Riss", description = "Ich habe dieses Samenkorn seit zehntausend Jahren bewacht. Und Ihr lasst zu, dass es in die Hände der Fal'dorei fällt!\n\nIch hätte Euch sterben lassen sollen.\n\nZahlt Eure Schuld zurück. Helft mir, das Samenkorn zurückzuholen.", sourceObjective = "Folgt Talwandler Farodin in die Tunnel von Falanaar.", completion = "Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42228] = { id = 42228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versteckte Stadt", description = "Orathiss hat das Samenkorn unterschätzt. Es zehrt an ihrer Kraft und verlangsamt sie.\n\nWir müssen sie einholen und das Samenkorn in Sicherheit bringen!", sourceObjective = "Folgt Orathiss durch die Tunnel von Falanaar und tötet sie.", completion = "<Energie pulsiert um das uralte Samenkorn herum.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42229] = { id = 42229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shal'Aran", description = "Da ihre Wächterin nun besiegt ist, könnte diese Kammer dort vorn ein perfektes Versteck sein.\n\nKommt mit.", sourceObjective = "Folgt Thalyssra, während sie Shal'Aran erkundet.", completion = "Ein vorübergehendes Heim wie dieses wird uns gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42230] = { id = 42230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürde des Talwandlers", description = "Das Samenkorn erwacht. Wenn es keine Energie erhält, wird es schnell verdorren und absterben.\n\nWir müssen das Samenkorn hier herausbringen und irgendwo einpflanzen, wo es sicher ist.\n\nIch bin nicht stark genug, eine solche Bürde zu schultern. Aber Ihr... Ihr strotzt vor lauter Kraft. Ich kann es spüren.\n\nBitte nehmt das Samenkorn.", sourceObjective = "Aktiviert den Signalgeber von Fal'adora im Tempel von Fal'adora.", completion = "<Das Samenkorn passt perfekt auf den Sockel und lässt sich mit einem deutlichen Einrastgeräusch versenken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42231] = { id = 42231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geheimnisvolle Paladin", description = "Uns scheint sich eine einmalige Gelegenheit zu bieten.\n\nEin kleiner Orden von Paladinen ist auf uns zugekommen und behauptet zu wissen, wo sich Tyrs Grabmal befindet. Sie sagten, sie seien die Beschützer dieses Kriegshammers, aber die uralte Waffe wäre jetzt in Gefahr.\n\nIch möchte, dass Ihr mit ihrem Anführer Travard sprecht, um mehr über das Artefakt herauszufinden.", sourceObjective = "Sprecht mit Travard in Dalaran.", completion = "Mein Orden hütet ein mächtiges Geheimnis. Wir sind die Hüter von Tyrs letzter Ruhestätte!\n\nDie Angriffe der letzten Tage beweisen, dass der Ort seines Grabs kein Geheimnis mehr ist. Wir müssen das heilige Relikt dort beschützen: die Silberne Hand!", sourceObjectiveStatus = "unverified-source-field" }
quests[42233] = { id = 42233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochbergstämme", description = "Unterstützt die Tauren vom Hochberg, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests am Hochberg ab.", completion = "Die Hochbergstämme danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42234] = { id = 42234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Valarjar", description = "Unterstützt die Vrykul von Sturmheim, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt 4 beliebige Weltquests in Sturmheim ab.", completion = "Die Valarjar danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42235] = { id = 42235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Westfall" }
quests[42236] = { id = 42236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Northern Barrens" }
quests[42237] = { id = 42237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Tanaris" }
quests[42238] = { id = 42238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisster Dämon", description = "Ich habe wohl meinen Wichtel Daglop verloren.\n\nSagt ihm doch, dass er sich bei mir melden soll, falls Ihr ihn seht.\n\nNormalerweise würde ich ihn einfach neu beschwören, doch ich befürchte, dass der blinde Marius ihn auf der Stelle töten und erst dann Fragen stellen würde.\n\nDem fehlt einfach der Weitblick.", sourceObjective = "Sucht nach Daglop in Azsuna.", completion = "Ja, ja, der neue Meister hat Euch geschickt. Ich versteh schon. Ich muss mich erst um meinen ehemaligen Meister kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[42239] = { id = 42239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Der Bärenkönig" }
quests[42240] = { id = 42240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Schwerfällige Wilderei" }
quests[42241] = { id = 42241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Eine würdige Herausforderung" }
