quests[42244] = { id = 42244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Revanche der Königin", description = "<Diese Art von Informationen sollte man mit anderen teilen. Vielleicht weiß jemand in Windläufers Zuflucht in Dalaran etwas damit anzufangen.>", sourceObjective = "Bringt das Logbuch des Kapitäns zu Beraterin Stillwasser in Windläufers Zuflucht in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "<Die Beraterin sieht sich an, was Ihr mitgebracht habt, und blickt sich dann nervös um. Mit einem gezwungenen Lächeln fährt sie in gedämpftem Ton fort.>\n\nWisst Ihr, was Ihr da gefunden habt? Ihr habt verhindert, dass die Allianz einige sehr sensible Informationen in ihre gierigen kleinen Finger bekommt.\n\nIch werde persönlich dafür Sorge tragen, dass sie an einem sicheren Ort abgelegt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42268] = { id = 42268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffbrüchige Matrosen", description = "<Die Gilblin und Makrura von Mak'rana haben die Matrosen der Verlassenen aus dem nahen Schiffswrack gefangen genommen.>\n\n<Es sieht so aus, als würden sie sehr schlecht behandelt. Also ist wohl eine Rettungsmission angebracht.>", sourceObjective = "Rettet 10 Matrosen der Revanche der Königin.", sourceObjectiveStatus = "unverified-source-field" }
quests[42269] = { id = 42269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelenräuber" }
quests[42270] = { id = 42270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel der Himmel" }
quests[42271] = { id = 42271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr letzter Atem", description = "Mir bleibt nicht viel Zeit. Meine Truppen sind jetzt gerade damit beschäftigt, einen Ansturm verdorrter Elfen zurückzuschlagen.\n\nDiese vier Welplinge sind dem Tode nahe. Ihre Leben sind für unseren Schwarm äußerst wichtig, denn wir wissen nicht, ob Senegos noch mehr Welplinge großziehen kann.\n\nEin paar gesprungene Leykristalle sollten sie wieder auf die Beine kommen lassen.", sourceObjective = "Beschafft 4 gesprungene Leykristalle und benutzt sie, um die manageschröpften Welplinge wiederzubeleben.", progress = "Oh nein...", completion = "Es war ja klar, dass sie genau jetzt angreifen.\n\nDiese verdorrten Teufel hätten keinen besseren Zeitpunkt wählen können. Meine Brut leidet schon darunter.", sourceObjectiveStatus = "unverified-source-field" }
