quests[42363] = { id = 42363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Mylune" }
quests[42365] = { id = 42365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fokussierte Energien", description = "Zusätzlich zu den Alptraumsplittern benötigen wir auch noch Blut von Sargeras, um das Portal zum Riss von Aln zu reaktivieren.\n\nDieses seltene Reagenz erhält man im Gebiet der Verheerten Inseln. Angeblich sollen ein paar Gesandte nach erfahrenen Abenteurern suchen und dieses Reagenz als Belohnung anbieten.", sourceObjective = "Sammelt 3 Proben des Bluts von Sargeras.", progress = "Konntet Ihr das Blut von Sargeras finden?", completion = "Ausgezeichnet, Erzdruide. Damit lässt sich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42366] = { id = 42366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je höher man steigt, desto teuflischer der Sturz", description = "Genug gekleckert, <mein kleiner Helfer/meine kleine Helferin>. Jetzt wird geklotzt!\n\nDer Foliant ist der Schlüssel! Der Schlüssel, um das Potenzial unseres Volkes zu entfesseln.\n\nMacht Euch keine Sorgen. Ich verfüge über genug Kraft, um die anstehende Aufgabe zu bewältigen. Lasst uns die Teufelsmagie nutzen und die Zukunft ändern.\n\nFolgt mir und werdet Zeuge der Rettung der Shal'dorei!", sourceObjective = "Helft Kyrtos bei seinem Ritual.", completion = "Kyrtos, Ihr alter Narr! Ihr hättet um die Risiken wissen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42367] = { id = 42367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkethrax", description = "Innerhalb des Vorstoßes befindet sich ein Dämon, der sterben muss.\n\nArkethrax ist eine Kreatur von hinterhältiger Bosheit. Wenn er unbeachtet bleibt, wird er in der Lage sein, den Vorstoß als Ausgangspunkt für gezielte und tödliche Angriffe auf unsere Streitkräfte zu nutzen.\n\nIch für meinen Teil habe nicht vor, diesen Gegner zu unterschätzen, und werde Euch auf dem Schlachtfeld beistehen, wenn Ihr bereit seid, ihm gegenüberzutreten.", sourceObjective = "Tötet Arkethrax.", completion = "Da Arkethrax und seine Schergen nun tot sind, sollten die Flanken des Verteidigungspostens der Illidari nicht mehr in Gefahr sein. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42368] = { id = 42368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quantität über Qualität", description = "Die Dämonen des Teufelsfeuervorstoßes sammeln sich in exponentieller Rate an.\n\nWir müssen diese Invasoren vernichten, bevor sie über genügend Dämonen verfügen, um unseren Streitkräften am Verteidigungsposten der Illidari in die Flanke zu fallen.\n\nWerdet Ihr unserem Kampf beistehen?", sourceObjective = "Tötet Dämonen im Teufelsfeuervorstoß.", completion = "Das sollte diese Dämonen für eine Weile aufhalten. Wir müssen in Zukunft möglicherweise zurückkehren, um sicherzugehen, dass sie sich nicht wieder neu formieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[42369] = { id = 42369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie machen es falsch", description = "Diese Dämonenportale sind geradezu furchtbar hingeschlampt. Ohne jegliche Finesse oder Können.\n\nDas tut mir geradezu körperlich weh... und ich habe schon jahrzehntelang keinen echten Schmerz mehr gespürt.\n\nIch habe einige dieser wertvollen Portalstabilisatorkristalle der Legion \"repariert\".\n\nIch möchte, dass Ihr damit ihr Hauptportal im Vorstoß \"modifiziert\" und den darauffolgenden \"Spaß\" begutachtet.", sourceObjective = "Platziert 4 sabotierte Portalstabilisatoren.", progress = "Habt Ihr den Gesichtsausdruck dieser Dämonen gesehen? Unbezahlbar!", completion = "Wenn Ihr glaubt, dass die Explosion auf unserer Seite des Portals gewaltig war, solltet Ihr erst mal die andere Seite sehen. Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[42370] = { id = 42370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Zauberstabkunde", description = "Wir werden mit etwas Zauberstabarbeit beginnen. Ihr habt Euren Zauberstab dabei? Gut.\n\nIch habe mehrere Ziele in der Halle aufgestellt. Nutzt Euren Zauberstab, um so viele wie möglich davon zu treffen.\n\nUnd keine Schüsse aus nächster Nähe! Das wäre Mogelei.", sourceObjective = "Übt an 10 Zauberstabzielen, Euren Zauberstab zu benutzen.", progress = "Ihr werdet nie lernen, wenn Ihr nie übt.", completion = "Und... es sieht so aus, als wäre die Zeit für die heutige Zauberstabübung abgelaufen. Dann weiter mit Euch. Auf zur nächsten Lehrstunde!", sourceObjectiveStatus = "unverified-source-field" }
quests[42371] = { id = 42371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Studiersaal: Kampfkunde", description = "Was haben wir denn hier? <Ein neuer, verwirrter Schüler, der/Eine neue> verwirrte Schülerin, die; ziel- und beschäftigungslos die Korridore durchstreift, ganz erpicht darauf, die Gunst der Direktorin zu gewinnen?\n\nPerfekt! Ich benötige Hilfe bei meiner Forschung.\n\nIch verfasse eine wissenschaftliche Arbeit über Kampftechniken. Holt mir ein paar Bücher aus dem Regal dort drüben.", sourceObjective = "Holt die Bücher, um die Sythorne Euch gebeten hat, und helft ihm dann, die darin beschriebenen Herausforderungen zu meistern.", progress = "Ganz Eurer Meinung. Forschung kann eine ganz grauenhafte Arbeit sein.", completion = "Mir wird die Hand von den ganzen Notizen schon ganz müde. Ich glaube, es ist an der Zeit, eine Pause zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42372] = { id = 42372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teufelsfeuervorstoß", description = "Es ist meine Aufgabe, Rückendeckung für den Verteidigungsposten der Illidari zu gewährleisten. Ich habe dieses Hexenmeister...ding in meine Dienste genommen, um mich zu unterstützen.\n\nEs gibt jedoch eine wichtige Aufgabe, der wir zwei allein nicht gewachsen sind.\n\nIm Osten befindet sich eine massive Ansammlung von Dämonen im Teufelsfeuervorstoß. Diese Kreaturen haben begonnen, Portale zu öffnen, um zahllose Verstärkungstruppen herbeizurufen.\n\nTrefft uns am Teufelsfeuervorstoß. Gemeinsam können wir diese Gefahr abwenden.", sourceObjective = "Trefft Euch mit Tehd Shumaker am Teufelsfeuervorstoß.", completion = "Senkt Eure Stimme, es sei denn, Ihr wollt unbedingt Teufelsfledermausfutter werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42373] = { id = 42373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Dunkelsteine" }
quests[42374] = { id = 42374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Greeting Kits - Tracking Quest" }
quests[42375] = { id = 42375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Auge behalten", description = "Blind zu sein, ist die eine Sache, dumm zu sein, eine andere.\n\nDieses augenlose Wunder neben mir will den Teufelsfeuervorstoß ohne Vorbereitung stürmen.\n\nPah! Ich sage, wir kundschaften ihn vorher aus.\n\nHier, ich gebe Euch ein zusätzliches Auge, das ich von einem besser nicht näher definierten Ort mitgenommen habe.\n\nBetretet den Teufelsfeuervorstoß, seht Euch um und seht zu, dass es nicht ins Auge geht.", sourceObjective = "Nutzt Tehds Auge von Kilrogg, um den Teufelsfeuervorstoß auszuspähen.", progress = "Fragt mich nicht, wo ich das Auge herhabe. Schlimmstenfalls erzähle ich es Euch und es endet wieder einmal in betretenem Schweigen.", completion = "Wie? Wie können ausgerechnet Dämonen so schlecht darin sein, ihre eigene Art zu beschwören?", sourceObjectiveStatus = "unverified-source-field" }
quests[42376] = { id = 42376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Tivos" }
quests[42377] = { id = 42377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Bruders Fersen", description = "Wir müssen die Silberne Hand sicherstellen, bevor jene, die Böses im Schilde führen, sie an sich reißen können. Um sie aus den Zauberschutzen zu entfernen, benötigen wir Relikte, die man die Funken von Tyr nennt. Ich habe einen davon und mein Bruder Galford einen weiteren.\n\nEr begab sich auf eine Reise nach Nordend, um Hilfe aus Tyrs Heimat zu erbitten, aber er kehrte nie zurück.\n\nIch möchte Euch bitten, ihn und seinen Funken zu finden.", sourceObjective = "Begebt Euch zur Drachenöde in Nordend und sucht nach Galford und seinem Funken von Tyr.", completion = "Ein schrecklicher Verlust. Doch Ihr habt seinen Funken und ich einen weiteren.\n\nWir müssen weitermachen. Um Galford werde ich später trauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[42381] = { id = 42381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ox'iloth" }
quests[42383] = { id = 42383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Der Irdene Ring baut auf die Stärke und Hingabe seiner Mitglieder.\n\nWenn wir diese Welt gegen die Brennende Legion verteidigen wollen, muss unser Orden wachsen und erfahrene Champions rekrutieren.\n\nBeginnt, indem Ihr mit Sturmruferin Mylra und Fürst Hydraxis sprecht. Vielleicht wären sie bereit, für uns zu kämpfen.", sourceObjective = "Rekrutiert Sturmruferin Mylra und Fürst Hydraxis.", completion = "Hervorragend. Sturmruferin Mylra und Fürst Hydraxis sind würdige Champions. Wir können darauf bauen, dass sie alle ihnen aufgetragenen Aufgaben ausführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42384] = { id = 42384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherberichte", description = "In letzter Zeit hat unser Orden kaum etwas anderes gemacht, als zu beobachten und abzuwarten. Da Ihr uns jetzt leitet, können wir uns wieder unserem ursprünglichen Ziel widmen.\n\nSeht Euch nur um, {name}. Azeroth braucht uns mehr als je zuvor. Der Feind, der einst zur Gründung unseres Ordens führte, ist erneut zur Bedrohung geworden.\n\nIhr solltet jemanden aussenden, die Berichte unserer Späher einzuholen. Dann können wir unsere Kräfte dort einsetzen, wo sie am meisten gebraucht werden.", sourceObjective = "Interagiert mit der Späherkarte und schließt die Mission \"Späherberichte\" ab.", completion = "Ich habe Berichte von unseren Spähern erhalten... und das gerade rechtzeitig, wie es scheint. Es gibt eine Menge Leute dort draußen, die unsere Hilfe benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42385] = { id = 42385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Unsere Späher haben gemeldet, dass ein Dorf in Val'sharah von untoten Hunden angegriffen wird.\n\nDas ist die perfekte Gelegenheit für den Unsichtbaren Pfad, unserem Versprechen Folge zu leisten, jenen in Not zu helfen.\n\nIhr solltet Euch auf den Weg nach Bradenbach machen, um zu sehen, was wir tun können.", sourceObjective = "Sucht nach Hudson Crawford in Val'sharah.", completion = "Ich weiß nicht, wer Euch geschickt hat, aber ich hoffe, Ihr seid gekommen, um zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42386] = { id = 42386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederkehrende Sorgen", description = "Unser Dorf wird von untoten Bestien überrannt!\n\nDiese Monstrositäten greifen unablässig Tag und Nacht an.\n\nWir geben unser Bestes, um sie in Schach zu halten, aber so langsam schwinden die Kräfte der Einwohner. Sie sind müde und bringen kaum noch den Willen auf, zu kämpfen.\n\nWir wären Euch sehr dankbar, wenn Ihr uns in dieser Sache aushelfen könntet.", sourceObjective = "Tötet auferstandene Hunde in und um Bradenbach herum.", completion = "Was immer Ihr da draußen gemacht habt, hat funktioniert. Die Angriffe dieser Hunde haben nachgelassen.\n\nHoffentlich können die Dorfbewohner jetzt etwas schlafen, um morgen wieder kampfbereit zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42387] = { id = 42387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attentäterfalle", description = "Die Invasoren der Rabenwehr greifen immer noch unsere Höfe und Heime an, obwohl es dort kaum noch etwas zu holen gibt.\n\nWir hatten gehofft, dass ihre Angriffe aufhören, wenn sie alles mitgenommen haben, aber diese hirnlosen Ghule folgen einfach allen Befehlen ihres Kommandanten.\n\nWir müssen ihn ausschalten, aber er ist ziemlich gerissen. Wir kriegen ihn nur, wenn wir ihm eine Falle stellen. Wenn Ihr dabei helft, besorge ich alles, was wir dafür benötigen.", sourceObjective = "Stellt eine Falle an Carlisles Hütte auf, um Hauptmann Tevaris zu fangen und zu töten.", completion = "Ich danke Euch, {name}. Ich glaube, unsere Kinder werden besser schlafen, wenn sie wissen, dass draußen vor der Tür jetzt keine Assassinen mehr herumschleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42388] = { id = 42388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Einbestellung", description = "Der Adler scheint eine Nachricht für Euch zu haben:\n\n\n\nUnsere Späher sind mit Berichten aus ganz Azeroth zurückgekehrt. Die Lage scheint schlimmer zu sein, als zunächst angenommen.\n\nKehrt, sobald es Euch möglich ist, zur Volltrefferhütte zurück.\n\n- Emmarel Schattenwächter", sourceObjective = "Sprecht mit Emmarel Schattenwächter in der Volltrefferhütte.", completion = "Ich bin so froh, dass wir wieder jemandem helfen können. Eure Arbeit in Bradenbach beweist, wie sehr der Unsichtbare Pfad benötigt wird.\n\nSeit Ihr uns verlassen habt, sind Unmengen an Berichten aus ganz Azeroth eingegangen. Da unsere Reihen ziemlich dünn sind, bin ich mir nicht sicher, ob wir mit all dem fertigwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42389] = { id = 42389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilaire heimrufen", description = "Es brauchen so viele Leute unsere Hilfe, dass wir vielleicht einige unsere Späher zurückrufen sollten.\n\nEine von ihnen ist eine Jägerin namens Hilaire. Sie hat zwar ihren Klan schon vor langer Zeit verlassen, um sich unserem Orden anzuschließen, aber sie fühlt sich immer noch dem Schutz ihrer Leute verpflichtet.\n\nEs ist bewundernswert, dass sie jene schützen möchte, die sie ablehnen, aber wir brauchen sie hier.\n\nSucht Hilaire in Sturmheim auf und sagt ihr, dass es an der Zeit ist, nach Hause zurückzukehren.", sourceObjective = "Sucht nach Bestienmeisterin Hilaire in Sturmheim.", completion = "Es ist schon eine Weile her, dass ich ein anderes Ordensmitglied getroffen habe.\n\nWenn Ihr wollt, dass ich mit Euch komme, muss ich Euch leider mitteilen, dass das nicht möglich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[42390] = { id = 42390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rexxar rekrutieren", description = "Um so viel Gutes wie möglich zu tun, brauchen wir die besten Jäger an unserer Seite.\n\nEuch als <Anführer/Anführerin> zu haben, ist natürlich ein guter Anfang. Um aber möglichst schlagkräftig zu sein, benötigen wir noch weitere Jäger mit exzellenten Fähigkeiten.\n\nRexxar gilt als einer der größten Jäger seiner Zeit, aber bis jetzt war er nie besonders gewillt, den Unsichtbaren Pfad zu unterstützen.\n\nEr unterhält ein Lager gleich nördlich von hier, von wo aus er mit Misha auf die Jagd geht. Vielleicht könnt Ihr ihn ja überzeugen, sich uns anzuschließen.", sourceObjective = "Sucht am Hochberg nach Rexxar.", completion = "Ihr seid von dieser Hütte am Berg, richtig? Ich habe von Eurem Orden gehört. Zweifelsohne eine respektable Gruppe, aber etwas zu träge für meinen Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[42391] = { id = 42391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biss der Bestie", description = "Ohne Cora gehe ich hier nicht weg.\n\nEin paar Magier halten sie wie eine wilde Bestie in einem Käfig gefangen und drohen damit, sie zu töten.\n\nSie sagen, sie wäre für den Tod eines der ihren verantwortlich, aber das glaube ich nicht. Cora ist eine treue und gehorsame Kameradin. Sie würde niemals ohne meinen Befehl angreifen.\n\nIch habe den Dämon, der wirklich für diese Tat verantwortlich ist, bis hierher verfolgt. Leider konnte er mir nach einem heftigen Kampf entwischen. Meine Verletzungen sind zu schwer, um ihn zu verfolgen, aber die Bestie hat bestimmt eine Blutspur hinterlassen.", sourceObjective = "Findet die Bestie, die für die Angriffe verantwortlich ist, und bringt ihren Kopf zu den Magiern, die Cora gefangen halten.", progress = "Ohne Cora gehe ich nirgendwo hin.", completion = "Danke, dass Ihr Coras Befreiung ermöglicht habt. Sie ist immer noch etwas ängstlich, aber sie wird sich bald erholt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[42392] = { id = 42392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben in der Nacht", description = "Jetzt könnt Ihr Eure Fertigkeiten auf die Probe stellen.\n\nEuer Orden scheint sich mehr auf das Beobachten und Abwarten als auf die Jagd zu konzentrieren.\n\nZeigt mir, dass ich mich irre und der Unsichtbare Pfad und ich tatsächlich etwas gemeinsam haben.\n\nWenn Ihr es schafft, eine Nacht in der Wildnis zu überleben, schließe ich mich vielleicht Eurem Orden an.", sourceObjective = "Überlebt eine Nacht am Klippenrand und befolgt dabei Rexxars Regeln.", completion = "Jetzt habt Ihr mich neugierig gemacht, {name}. Es gelingt nicht vielen Jägern, eine Nacht in diesen unwirtlichen Bergen zu überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[42393] = { id = 42393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedersehen", description = "Cora hat sich genug beruhigt, um die Reise zurück zur Volltrefferhütte anzutreten.\n\nIhr könnt Emmarel mitteilen, dass wir auf dem Weg nach Hause sind.", sourceObjective = "Kehrt zu Emmarel Schattenwächter in der Volltrefferhütte zurück.", completion = "Es ist so gut, dass Hilaire wieder zurück in der Hütte ist. Ihre Entschlossenheit und ihre Fertigkeiten werden uns in nächster Zeit sehr nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42394] = { id = 42394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichtbarer Schutz", description = "Wir werden Dalaran niemals aufgeben.\n\nWenn die Legion einen Angriff plant, wird der Unsichtbare Pfad eingreifen und sie aufhalten.\n\nLaut der neuesten Berichte unserer Späher gibt es aber noch andere Gegenden, die unsere Hilfe brauchen könnten. Manche wissen es vielleicht noch nicht einmal.\n\nSchickt Eure Jäger aus, um die Bedrohungen zu beseitigen, sobald Ihr bereit seid.", sourceObjective = "Verwendet die Späherkarte und entsendet Eure Champions und Trupps auf Missionen der Reihe \"Unsichtbarer Schutz\".", completion = "Ob sie es wissen oder nicht, die Völker von Azeroth haben dem Unsichtbaren Pfad ihre Sicherheit zu verdanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[42395] = { id = 42395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein gutes Zeichen", description = "Vor langer Zeit gaben wir ausgewählten Anführern besondere Leuchtfeuer, die nur in Zeiten größter Not eingesetzt werden sollten.\n\nSobald das Leuchtfeuer erblickt wurde, muss sich der Anführer des Unsichtbaren Pfads zum südlichen Wachturm begeben und sich mit demjenigen treffen, der das Signal gegeben hat.\n\nIch weiß nicht, wer uns am Turm erwarten wird, aber wir müssen rasch aufbrechen.", sourceObjective = "Trefft Emmarel oben auf dem südlichen Wachturm.", completion = "Ich fürchte, die Brennende Legion plant, in Dalaran einzufallen.\n\nIch habe einige Kirin Tor ausgeschickt, um verschiedene Dämonenfestungen auszuspionieren, und hoffe, dass sie Pläne aufdecken können, die die Stadt betreffen.\n\nIn der Zwischenzeit könnte Dalaran den Schutz des Unsichtbaren Pfads brauchen. Ich weiß, die Bürger werden in Sicherheit sein, wenn der Unsichtbare Pfad über sie wacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42396] = { id = 42396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erledigt das!", description = "Mrglrg! Mrlglr mrgllrg.\n\n<Phin gestikuliert wild umher.>\n\nMrlgrlg glrglmglr mrlglrg. Rglrgmrg mrglr glr. Glr! Gmrlgrmlg mrglmrgm...\n\n<Phin schaut Euch erwartungsvoll an.>", completion = "<Phin packt Euch bei den Schultern und hüpft glücklich auf und ab.>\n\nMlrglr! Grlrlrglrmg." }
quests[42397] = { id = 42397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron und der Jäger", description = "Khadgar hat uns mitgeteilt, er habe den Kontakt zu den Magiern verloren, die er zur Untersuchung der Legionslager ausgeschickt hatte. Er hat unsere Hilfe erbeten, um sie ausfindig zu machen.\n\nWenn wir diese Magier irgendwie finden wollen, brauchen wir einen zuverlässigen Spürhund.\n\nIch kenne nur einen derartigen Hund und der ist schon lange nicht mehr im Dienst. Wir sollten dennoch bei seinem Herrn, Jäger Blake, nachfragen, ob der alte Baron noch das Zeug dazu hat.", sourceObjective = "Findet Jäger Blake in Sturmheim.", completion = "Ihr habt die lange Reise auf Euch genommen, nur um Baron zu treffen? Wir hatten schon lange keine Besucher mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[42398] = { id = 42398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschärfte Sinne", description = "Ich fürchte, der alte Baron ist nicht mehr der Jüngste. Seine Nase kann einen Geruch nicht mehr so gut aufnehmen wie früher. Man hat mir schon geraten, ihn einschläfern zu lassen, aber ich kann den Gedanken nicht ertragen, meinen treuen Freund zu verlieren.\n\nBei der Arbeit ging es Baron allerdings immer am besten. Vielleicht erlaubt Ihr ihm, durch diese Felder zu streifen und ein paar alte Knochen auszubuddeln. Das dürfte seine Sinne wieder schärfen.", sourceObjective = "Helft Baron, seine Sinne zu schärfen, indem er in der Umgebung uralte Knochen ausgraben darf.", progress = "Wie macht der alte Baron sich?", completion = "Ich weiß ja nicht, was für Knochen Ihr und Baron auf diesen Feldern gefunden habt, aber so übermütig war er das letzte Mal als kleiner Welpe!", sourceObjectiveStatus = "unverified-source-field" }
quests[42399] = { id = 42399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Arbeit", description = "Wenn Baron einsatzbereit ist, bin ich es auch.\n\nWir gehen zur Jagdhütte, sobald ich das Lager abgebrochen und diesen Hund gefüttert habe. Ich bin sicher, dass er nach dem vielen Graben bestimmt großen Appetit hat.", sourceObjective = "Kehrt zu Emmarel Schattenwächter in der Volltrefferhütte zurück.", completion = "{class} Blake anzuwerben, war gute Arbeit. Sein Hund könnte der Schlüssel sein, um Khadgars Magier aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[42400] = { id = 42400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene Magier", description = "Der Erzmagier hat sich bereits nach Suramar begeben, wo man die vermissten Magier zuletzt gesehen hat.\n\nBaron ist auch losgerannt. Scheinbar ist der Hund begierig, wieder zu arbeiten.\n\nTrefft die beiden nahe der Straße, die in die Stadt führt. Mit ein wenig Glück kann Baron den magischen Geruch der Magier aufnehmen und sie finden, bevor es zu spät ist.", sourceObjective = "Trefft Erzmagier Khadgar in Suramar.", completion = "Danke, dass Ihr Euch mit mir trefft, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42401] = { id = 42401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch der Magie", description = "Dies ist der letzte bekannte Aufenthaltsort der verschwundenen Kirin Tor. Es gibt nicht viele Anhaltspunkte, nur einen Fetzen Stoff, der von einem unserer Waffenröcke stammen könnte.\n\nDer Fetzen ist zwar klein, aber er müsste mit magischer Essenz durchtränkt sein. Wir können nur hoffen, dass Baron den Geruch aufnehmen und die Magier aufspüren kann.", sourceObjective = "Folgt Baron, während er der Spur der Magier folgt.", completion = "Der Hundemeister ist ein uralter und mächtiger Dämon, der unsere Welt schon einmal angegriffen hat.\n\nSeine Rückkehr könnte furchtbare Konsequenzen für Magier in ganz Azeroth haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[42402] = { id = 42402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung anfordern", description = "Viele mächtige Fraktionen haben dem Unsichtbaren Pfad ihre Treue geschworen. Wir sollten sie zusammenrufen, damit sie uns helfen, Hakkar und seine Dämonenhunde zu besiegen.\n\nSchickt Eure Champions ins Feld. Sie sollen die Anführer finden und wissen lassen, dass wir ihre Hilfe benötigen.", sourceObjective = "Interagiert mit der Späherkarte und schließt die Mission \"Verstärkung anfordern\" ab.", completion = "Unsere Verbündeten haben sich alle hier in der Hütte versammelt und warten auf den jüngsten Lagebericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42403] = { id = 42403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochbergjäger", description = "Ich habe gerade von unseren Spähern erfahren, dass sie einige potentielle Rekruten ausgemacht haben.\n\nScheinbar hat der berühmte Hemet Nesingwary sein Lager nicht allzu weit von unserer Hütte entfernt aufgeschlagen.\n\nEr gehört zwar nicht zur üblichen Sorte Jäger, die wir zu uns einladen, aber seine Erfahrung in der Jagd auf Großwild könnte sehr nützlich sein.\n\nGeht zu seinem Rückzugsort und fragt ihn, ob er bereit ist, unsere Sache zu unterstützen.", sourceObjective = "Findet Hemet Nesingwary am Hochberg.", completion = "Ihr seid von der Jagdhütte auf dem Hügel, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[42404] = { id = 42404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Erzmagier", description = "Hakkar unterhält eine Armee aus Teufelshunden, die sich von Magie ernähren. Solange er sich in Azeroth aufhält, wird kein Magier sicher sein.\n\nEr und seine Hunde sind den meisten Zaubern gegenüber immun, also brauche ich Hilfe, um sie zu töten.\n\nIhr habt Euch als äußerst fähig erwiesen, aber seid Ihr bereit, bei der Vernichtung dieses Dämons zu helfen?", sourceObjective = "Kehrt zu Emmarel Schattenwächter in der Volltrefferhütte zurück.", completion = "Wenn wir helfen können, sollten wir helfen. Hakkar ist in unserer Welt nicht willkommen und seine Anwesenheit darf nicht geduldet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42405] = { id = 42405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbündeten alarmieren", description = "Die Anführer einiger der größten Militärfraktionen sind hier und wollen helfen.\n\nSie warten darauf, direkt mit Euch sprechen zu können, und wollen Euch erklären, wie ihre Hilfe aussehen könnte.\n\nMit ein bisschen Glück können wir unsere Mittel bündeln und einen Weg finden, um Hakkar zur Strecke zu bringen.", sourceObjective = "Sprecht mit Erzmagier Khadgar, Halduron Wolkenglanz, Vereesa Windläufer und Shandris Mondfeder.", completion = "Gegen die vereinten Kräfte der Fraktionsführer unter Eurer Führung hat Hakkar keine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[42406] = { id = 42406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Tief im Herzen von Faronaar liegen Höhlen, die von Teufelshunden überrannt sind. Wenn Hakkar diese Biester züchtet, dann würde er es genau dort tun.\n\nDer Köder, den ich hergestellt habe, ist sehr wirksam. Sobald Ihr ihn auslegt, wird er die Aufmerksamkeit aller Hunde im Umkreis auf sich ziehen, also verwendet ihn nur, wenn Ihr nah genug bei den Höhlen seid.\n\nSobald der Dämon den Köder geschluckt hat, müsst Ihr ihn schwächen, damit er leichter einzufangen ist.\n\nViel Glück, {name}. Ich hoffe, Ihr kehrt unversehrt zurück.", sourceObjective = "Verwendet den Leywurmköder in den Höhlen der Teufelsbestien, um einen Teufelshundnestling anzulocken und zu fangen.", progress = "Achtet darauf, die Teufelshunde zu fangen und nicht zu töten. Ich brauche sie lebend für meine Tests.", completion = "Der Hundemeister hat mit dieser Teufelshunderasse einige interessante Dinge angestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42407] = { id = 42407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wesen der Bestie", description = "Dieser Dämon ist von Natur aus resistent gegen Magie, aber gleichzeitig wurde er darauf gezüchtet, körperlichen Angriffen zu widerstehen. Er ist mit mehreren Schichten dicker Schuppen bedeckt, wie ich sie noch nie zuvor gesehen habe. Ich glaube, die wenigsten Metalle wären in der Lage, die rüstungsartige Haut des Dämons zu durchbohren.\n\nWenn Ihr nicht Eure gesamte Armee mit Waffen wie der Eurigen ausstatten wollt, schlage ich vor, dass wir diese Biester mit etwas bekämpfen, das ihre Schwäche ausnutzt.", sourceObjective = "Kehrt zu Emmarel Schattenwächter in der Volltrefferhütte zurück.", completion = "Das sind beunruhigende Neuigkeiten. Wenn unsere Waffen nichts gegen Hakkars Diener ausrichten können, wie sollen wir sie dann besiegen?\n\nWir sollten unsere Verbündeten zusammenrufen und sehen, wie sie uns helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[42408] = { id = 42408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Reagenzien", description = "Die Schildwachen kennen eine vertrauenswürdige und talentierte Verzauberin, die sich auf Verzauberungen gegen Dämonen spezialisiert hat.\n\nSie stellt ihre Dienste den Schildwachen kostenlos zur Verfügung, aber sie benötigt gewisse Reagenzien, um ihre Verzauberungen vornehmen zu können.", sourceObjective = "Sammelt die erforderlichen Reagenzien.", progress = "Der Verzauberungsvorgang ist ohne die nötigen Reagenzien nicht möglich.", completion = "Das sollte genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42409] = { id = 42409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Loren Sturmhuf", sourceObjective = "Ich habe Euch erwartet, {name}. Ohn'ahras Erscheinen deutete auf eine Veränderung hin.\n\nDie Hochbergstämme sind schon lange mit dem Unsichtbaren Pfad verbündet.\n\nMeine Vorfahren haben Namuria und ihre {class} in unserem Land begrüßt und gemeinsam haben wir die Hütte gebaut, in der Ihr nun steht.\n\nEs ist mir eine Ehre, an Eurer Seite zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42410] = { id = 42410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rexxar", sourceObjective = "Eine alte Bedrohung ist wieder aufgetaucht und sie ist stärker als je zuvor. Azeroth braucht {class} wie Euch, die um jeden Preis überleben wollen.\n\nAls Anführer des Unsichtbaren Pfads werden sich viele hilfesuchend an Euch wenden. Zeigt ihnen, dass sie überleben können.\n\nIch werde Euch beistehen und gemeinsam werden wir die Botschaft aussenden, dass auch im Angesicht eines mächtigen Feindes wie der Brennenden Legion der Wille überdauern kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[42411] = { id = 42411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Bestienmeisterin Hilaire", sourceObjective = "Ich wusste, es war nur eine Frage der Zeit, bis wir Späher nach Hause zurückgerufen würden.\n\nIch habe hier in den letzten Jahren nicht viel zu tun gehabt. Andererseits haben aber in letzter Zeit einige Klans ihren Traditionen abgeschworen und sich einem König angeschlossen, der auf Seiten der Legion steht.\n\nDie Leute, die ich zu beschützen gelobte, haben sich also mit meinem Feind verbündet. Ich werde nicht zulassen, dass andere dasselbe Schicksal ereilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42412] = { id = 42412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Jäger Blake", sourceObjective = "Ihr habt einen alten Mann zu Tränen gerührt, indem Ihr Baron wieder zum Leben erweckt habt. Ich hätte nie gedacht, dass ich sein ohrenbetäubendes Gejaule vermissen würde, aber so war es. Es ist schön, ihm wieder bei der Arbeit zuzusehen.\n\nWir werden immer gerne helfen, wenn wir gebraucht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42413] = { id = 42413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hemet Nesingwary", sourceObjective = "Den Vogel vom Himmel zu holen, war eine klasse Leistung.\n\nVielleicht hab ich mich doch geirrt, was Euch {class} da oben in der Hütte angeht. Ihr wisst offenbar, was Ihr tut.\n\nIch jage gerne wieder mit Euch, solange es um Großwild geht!", sourceObjectiveStatus = "unverified-source-field" }
quests[42414] = { id = 42414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Addie Zischmoor", sourceObjective = "Ich glaube, nicht einmal Hemet selbst hätte mich besser unterrichten können, aber ich muss daran glauben, dass zur Jagd mehr gehört, als nur Großwild zur Strecke zu bringen.\n\nWenn ich bei Euch bleibe, werde ich sicher lernen können, was es heißt, ein wahrer {class} zu sein.\n\nEin Hoch auf Euch und die vielen großen Abenteuer, die auf uns warten!", sourceObjectiveStatus = "unverified-source-field" }
quests[42415] = { id = 42415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Halduron Wolkenglanz", sourceObjective = "Ihr habt mit mehr Mut und Kraft gegen Hakkar gekämpft, als ich seit langer Zeit gesehen habe.\n\nWie Emmarel schon gesagt hat: Unser Kampf gegen die Legion hat gerade erst begonnen. Aber auf eins könnt Ihr Euch verlassen: Die Weltenwanderer sind da, wenn Ihr uns braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42416] = { id = 42416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rat tagt", description = "Dass sich Erzmagier Vargoth mit der Empyreumgesellschaft abgibt, ist beunruhigend. Allerdings hat er seine Loyalität zu den Kirin Tor schon oft unter Beweis gestellt, also sollten wir ihn nicht allzu schnell verurteilen.\n\nDennoch muss jemand dem Rat unsere Bedenken vortragen. Ihr reist am besten nach Dalaran und trefft Euch mit dem Rat in der Violetten Zitadelle. Ich werde hierbleiben und mich um unseren alten Freund kümmern.", sourceObjective = "Sprecht mit dem Rat der Sechs in Dalaran.", completion = "Es wäre natürlich schockierend, wenn sich herausstellen sollte, dass Erzmagier Vargoth tatsächlich mit Teufelsmagie herumexperimentiert. Aber trotzdem danke ich Euch, dass Ihr uns darüber in Kenntnis gesetzt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42417] = { id = 42417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilebrain" }
quests[42418] = { id = 42418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwarteter Besucher", description = "Erzmagier Vargoths langjähriger Lehrling, Ravandwyr, ist mit einer dringenden Nachricht von seinem Mentor hier in der Halle des Wächters eingetroffen.\n\nEr wartet oben auf Euch. Ihr sucht ihn besser schnell auf, {name}!", sourceObjective = "Trefft Euch mit Ravandwyr.", completion = "Haben wir uns schon einmal gesehen? Euer Gesicht kommt mir irgendwie bekannt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[42420] = { id = 42420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farondis' Hofstaat", description = "Unterstützt Farondis' Hofstaat in Azsuna, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests in Azsuna ab.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung von Farondis' Hofstaat abgeschlossen habt, {name}.", completion = "Farondis' Hofstaat dankt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42421] = { id = 42421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtsüchtigen", description = "Unterstützt die Nachtsüchtigen von Suramar, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests in Suramar ab.", progress = "Helft uns, und wir werden Euch belohnen.", completion = "Die Nachtsüchtigen danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42422] = { id = 42422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächterinnen", description = "Unterstützt die Wächterinnen, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt 4 Weltquests der Wächterinnen ab.", completion = "Die Wächterinnen danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42423] = { id = 42423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzmagier Vargoths Rückzugsort", description = "Erzmagier Vargoth war eine Zeitlang nicht hier. Ihr könnt Euch gern seine Gemächer hier im Turm der Zitadelle ansehen, {name}. Kalec wird Euch dorthin geleiten.\n\nIch hoffe sehr, dass unser geschätzter Kollege nur wieder einmal seinen exzentrischen Neigungen nachgeht.", sourceObjective = "Untersucht die Gemächer von Erzmagier Vargoth.", progress = "Was habt Ihr herausgefunden, {name}?", completion = "Hm... Das scheinen Erzmagier Vargoths Notizen über den Seelenstein der Nachtgeborenen zu sein. Demnach geht er davon aus, dass die Energien der darin gespeicherten Seelen direkt aus dem Stein heraus kanalisiert werden können! Wenn das wahr ist, wäre er tatsächlich sehr mächtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[42424] = { id = 42424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spurensuche", description = "Erzmagier Vargoth scheint sich auf ein paar gefährliche Dinge eingelassen zu haben. Aber das ist ja nichts Ungewöhnliches für einen erfahrenen Erzmagier seines Kalibers!\n\nEr ist möglicherweise auf dem Weg zum Arkusgewölbe, aber wir sollten allen Hinweisen folgen, um seine Pläne besser nachvollziehen zu können.", sourceObjective = "Bittet Eure Champions, die Bewegungen von Erzmagier Vargoth zu verfolgen.", completion = "Gute Neuigkeiten! Euer Champion hat Erzmagier Vargoth gefunden, wie er gerade das Arkusgewölbe in Suramar betrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[42425] = { id = 42425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnell runter, schnell raus", description = "Jetzt, da wir die benötigten Wurminnereien haben, war ich in der Lage, sie zu einem speziellen Seil zu verarbeiten.\n\nEs wird Euch gestatten, Euch von der Brücke in den Abgrund darunter abzuseilen und einige meiner Besitztümer zurückzuholen, die von den Steintiefendrogbar gestohlen und dort hinabgeworfen wurden.", sourceObjective = "Nutzt Orens Kletterstelle, um Euch in die Tiefe abzuseilen und seine verlorenen Besitztümer zurückzuholen.", progress = "Ich konnte großen Höhen noch nie etwas abgewinnen.", completion = "Ich kann's nicht glauben! Ich hatte gehofft, es würde funktionieren, war mir jedoch nicht sicher.\n\nIhr habt Erbstücke wiederbeschafft, die in meiner Familie über Generationen weitergereicht wurden.\n\nIch dachte, sie wären auf ewig verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[42426] = { id = 42426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Test Enabled" }
quests[42427] = { id = 42427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42428] = { id = 42428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashamanes Schrein", description = "Die mächtige Urahne Ashamane kam vor zehntausend Jahren in der Schlacht gegen die Legion zu Fall. Um ihr Opfer zu ehren, haben die Äschernen, eine ihr treu ergebene Gruppe von Druiden, aus Ashamanes Reißzähnen mächtige Dolche erschaffen.\n\nNehmt mein Signet und zeigt es ihrem Anführer Delandros Schimmermond. So wird er wissen, dass Ihr meinen Zuspruch habt.\n\nUnsere Flugmeisterin Danise Sternenspäher kann dafür sorgen, dass Ihr zum Schrein gelangt.", sourceObjective = "Sprecht mit Danise Sternenspäher und reist nach Ashamanes Sturz, um nach Delandros Schimmermond zu suchen.", completion = "Rensar hat Euch geschickt? Ich würde Euch sehr gern helfen, aber das muss jetzt leider warten. Im Augenblick haben wir hier größere Probleme, wie Ihr sehen könnt.\n\nEigentlich könnten wir eher Eure Hilfe gebrauchen. Wenn Ihr uns helft, werde ich Euch bei dem unterstützen, weshalb Ihr hergekommen seid.\n\nSeid Ihr einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[42429] = { id = 42429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an Schwarzfrost", description = "Habt Ihr da etwa Schwarzfrost? Alodis alten Stab? Meine Güte... <Hust>\n\nIn den Tagen des ersten Wächters haben alle Mitglieder des Rates von Tirisfal dem jungen Magier ihre Mächte überlassen. Sie hofften, so die Legion zu überwältigen. <Keuch> Inzwischen sind sie alle dahingeschieden... doch Euer Stab erinnert sich.\n\nSucht unter uns in den Straßen von Dalaran nach den Abbildern der ehemaligen Ratsmitglieder. Ihre Erinnerungen können Euch ermächtigen, wie sie es einst mit Alodi getan haben. Sucht sie auf und sprecht mit einem von ihnen!", sourceObjective = "Sucht nach einem Abbild eines Mitgliedes des Rates von Tirisfal in Dalaran. Sprecht mit dem Abbild, um dessen Weisheit zu erhalten.", completion = "Ah, Eure Augen erstrahlen vor neuem Wissen, {name}.\n\n Euer Stab hat den Verlauf vieler Lebzeiten miterlebt.  Er kann Euch viele Dinge lehren, wenn Ihr nur zuhört.\n\nWas seine Erinnerungen betrifft... die sind nicht unbedingt zuverlässig. Jeden Tag kann ein anderes Spiegelbild in den Straßen von Dalaran spuken. Es ist Euch überlassen, sie alle zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42430] = { id = 42430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fänge von Ashamane", description = "Ich muss zugeben, dass Verstok recht hatte. Der Schrein war ein zu leichtes Angriffsziel für die Brennende Legion. Aber er ist fort und mit ihm auch die Fänge.\n\nWir müssen ihn aufspüren, damit Ihr die Fänge zurückholen könnt. Ich würde mit Euch gehen, aber ich muss hier bei meinen Leuten bleiben, falls wir noch einmal angegriffen werden.\n\nHier, mein Begleiter Schwarzzahn hat einen unvergleichlichen Spürsinn. Er wird Euch zu Verstoks Versteck führen. Nehmt auch diese Muschel mit, wir können durch sie kommunizieren.\n\nMöge Elune Euch beistehen.", sourceObjective = "Steigt auf den Rücken von Schwarzzahn und sucht nach den Fängen von Ashamane.", completion = "Ich habe von Delandros gehört, dass Ihr die Äschernen gerettet und den Schrein beschützt habt.\n\nFür diese Heldentaten stehen wir tief in Eurer Schuld, {name}. Und wie ich sehe, habt Ihr auch noch die Fänge zurückgeholt!\n\nIch vermute, dieser Krieg ist noch lange nicht vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[42431] = { id = 42431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nithoggs Brut" }
quests[42432] = { id = 42432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Der Smaragdgrüne Alptraum", description = "Der Herr des Alptraums, Xavius, ist noch immer dort draußen. Tief im Riss von Aln schwebt Cenarius weiterhin in großer Gefahr.\n\nRuft Eure größten Verbündeten zusammen, {name}. Wenn wir dem Alptraum ins Gesicht blicken wollen, müssen wir bereit sein.\n\nWenn Ihr es seid, betretet den Smaragdgrünen Alptraum und besiegt all die Schrecken, die Euch dort erwarten.", sourceObjective = "Betretet den Smaragdgrünen Alptraum auf einem beliebigen Schwierigkeitsgrad und besiegt Lord Xavius.", completion = "Endlich siegreich, {name}! Mit dem Sieg über Xavius wird die Präsenz des Alptraums sich langsam aus dem Smaragdgrünen Traum zurückziehen.\n\nDas besinnliche Reich der Schläfer ist wieder sicher. Unsere Druiden werden sich um dessen Wiederherstellung kümmern.\n\nVielen Dank, Erzdruide {name}. Dank Euch wird Azeroth noch viele ruhige Tage und friedliche Nächte erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[42433] = { id = 42433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Magie", description = "Da die Verheerten Inseln den Mittelpunkt für die Lehren der uralten Nachtelfen darstellen, müssen hier unzählige magische Artefakte in vergessenen Gewölben und Reliquienschreinen verborgen liegen. Wir müssen sie bergen, damit sie nicht in die falschen Hände geraten!\n\nVielleicht solltet Ihr einen Champion auf die Suche danach aussenden.", sourceObjective = "Interagiert mit Eurer Späherkarte und schließt die Mission \"Uralte Magie\" ab.", completion = "Euer Champion hat einige sehr mächtige Artefakte entdeckt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[42434] = { id = 42434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geheimoperation", description = "Euer Champion hat eine seltsame, mächtige Energieform entdeckt, die von der geheimen Enklave der Empyreumgesellschaft in Azsuna auszugehen scheint.\n\nErzmagier Vargoth wollte, dass ich Meryl mit der Untersuchung dieses Phänomens beauftrage, aber wie Ihr sehen könnt, ist Meryl eindeutig noch viel zu krank, um zu reisen. Wärt Ihr bereit, seine Aufgabe zu übernehmen?\n\nUm eingelassen zu werden, müsst Ihr Euch erst beweisen. In der Kriegsbasis der Hassnattern in Azsuna sollte es etwas geben, das den Zweck erfüllt.", sourceObjective = "Trefft Euch mit Ravandwyr in Azsuna.", completion = "Gut. Ihr habt mich gefunden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42435] = { id = 42435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit machen zur Assimilation", description = "Die Empyreumgesellschaft ist ein gefährlicher Kult. Sie behaupten zwar, dass sie sämtliche Bereiche der Magie erforschen, doch in Wahrheit konzentrieren sie sich hauptsächlich auf das Verbotene. Wenn Ihr ihnen ein magisches Artefakt bringt, werden sie Euch in ihrer Enklave willkommen heißen.\n\nDie Hassnattern sind im Besitz der perfekten Geschenke: eine Perle der arkanen Weisheit sowie Schriftrollen, die in den Tiefen unter der Akademie von Nar'thalas verloren gingen. Ihr werdet sie überzeugen müssen, sich von einigen zu trennen.\n\nIch treffe Euch dann an der Straße gleich nördlich der Empyreumenklave.", sourceObjective = "Besorgt die Perle der arkanen Weisheit und 5 Schriftrollen von Nar'thalas und trefft Euch mit Ravandwyr nördlich der Empyreumenklave.", progress = "Habt Ihr die Perle und Schriftrollen gefunden?", completion = "Gut. Jetzt sollten wir die Enklave der Empyreumgesellschaft betreten und uns ein wenig umsehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[42436] = { id = 42436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für unsere Verbündeten", description = "Unsere Verbündeten vom Himmelshorn könnten unsere Hilfe brauchen.\n\nAufgrund des fortdauernden Krieges gegen die eindringenden Harpyien gehen ihre Vorräte zur Neige.\n\nAlles, was wir ihnen liefern können, wird ihnen helfen, diese Hexen aus ihrem Dorf zu vertreiben.", sourceObjective = "Bringt Vorräte zu Meliah Graufeder.", completion = "Dank Eures Einsatzes ist unser Bündnis mit den Himmelshörnern stärker als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[42437] = { id = 42437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Starbuck" }
quests[42438] = { id = 42438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saat der Erneuerung", description = "Die Fänge von Ashamane sind in Gefahr, {name}. Seit Zehntausenden von Jahren werden sie von einem mächtigen Zauberschutz vor Dieben geschützt. Aber im Laufe der Zeit hat dieser Schutz so weit nachgelassen, dass er womöglich versagen könnte. Ich habe meinen drei treuesten Äschernen die Samenkörner von Tel'andu übergeben, die wir für das Ritual der Erneuerung benötigen. Aber die Wälder wimmeln jetzt nur so von Dämonen und ich fürchte, dass die drei gefallen sind.\n\nWir dürfen die Fänge auf keinen Fall der Legion überlassen! Geht und findet die Samenkörner von Tel'andu. Wir müssen uns beeilen, bevor der Schutz durchbrochen werden kann!", sourceObjective = "Delandros Schimmermond möchte, dass Ihr die Wälder des Nebelgrunds absucht und die drei Samenkörner von Tel'andu beschafft.", progress = "Habt Ihr die Samenkörner von Tel'andu?", completion = "Ich danke Euch, {name}.\n\nMein Herz weint um jene, die wir heute verloren haben. Dafür wird die Legion bezahlen, das schwöre ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[42439] = { id = 42439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Äschernen", description = "Richtet Euren Blick nach oben, dann seht Ihr den Grund für unsere Misere. Seit dieses Schiff aufgetaucht ist, sind die Angriffe immer unerbittlicher geworden. Viele der Äschernen sind gefangen genommen worden und ich kann ihre gequälten Schreie bis hier hören.\n\nBitte zieht los und rettet so viele meiner Leute, wie Ihr nur könnt. Das Schicksal, das ihnen in den Händen der Legion droht, haben sie nicht verdient.", sourceObjective = "Besiegt 4 Seelenfolterer der Eredar und befreit ihre Gefangenen.", completion = "<Delandros nickt.>\n\nIch danke Euch. Meine Leute sind in Sicherheit. Jetzt haben wir vielleicht die Möglichkeit, diesen Krieg zu unseren Gunsten zu wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42440] = { id = 42440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrein in Gefahr", description = "Ihr habt uns einen großen Dienst erwiesen, Champion. Jetzt erzählt mir bitte, was Euch hierhergeführt hat.\n\n<Ihr erzählt Delandros, dass Erzdruide Großhuf Euch geschickt hat, um die Fänge von Ashamane in Euren Besitz zu bringen.>\n\nHm... Wenn Ihr mir das gleich erzählt hättet, hätte ich Euch davongejagt. Die Fänge sind unser größter Schatz, aber Ihr wart den Äschernen heute eine große Hilfe und ich bin ein Elf, der sein Wort hält.\n\nAlso gut, lasst uns die verbleibenden Dämonen auslöschen, dann bekommt Ihr Eure Waffen.", sourceObjective = "Helft Delandros, indem Ihr die verbleibenden Angreifer auslöscht.", progress = "Habt Ihr diese Störung untersucht?", completion = "Was? Verstok ist mit den Fängen geflohen? Dieser Narr! Das wird ihn noch das Leben kosten!", sourceObjectiveStatus = "unverified-source-field" }
quests[42442] = { id = 42442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht: Amalia" }
quests[42443] = { id = 42443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arluin Wants In (Tracking Quest)" }
quests[42444] = { id = 42444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Notlage der Schwarzfedern", description = "<Der Rabenbär gestikuliert aufgeregt und zeigt den Pfad hinunter.\n\nEr möchte offenbar, dass Ihr ihm folgt.>", sourceObjective = "Folgt dem verängstigten Rabenbären zum Häuptling der Schwarzfedern.", completion = "Krah!?\n\n<Der Rabenbärhäuptling scheint sehr beschäftigt damit zu sein, ein paar Reagenzien für eine Art Ritual zu sammeln. Vielleicht könntet Ihr ihm dabei helfen?>", sourceObjectiveStatus = "unverified-source-field" }
quests[42445] = { id = 42445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nithoggs Tribut", description = "Die Rabenbären scheinen damit begonnen zu haben, Materialien für eine Art Tributritual zu sammeln, aber die Sturmdrachen halten sie davon ab.\n\nOffensichtlich benötigen sie vollständig intakte Geweihe von den Großhirschen und lange Schwanzfedern von den Adlern in der Nähe.\n\nEs sollte nicht allzu lange dauern, die restlichen Materialien herbeizuschaffen.", sourceObjective = "Sammelt 8 intakte Großhirschgeweihe und 16 makellose Adlerschwanzfedern im Sturmgepeitschten Vorgebirge.", progress = "Krah-krah?", completion = "Krah! Krah!\n\n<Der Rabenbärhäuptling schlägt aufgeregt mit den Flügeln, als er die Reagenzien sieht, die Ihr ihm mitgebracht habt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42446] = { id = 42446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesengte Federn", description = "Krah! Krah-krah!\n\n<Der Häuptling schlägt mit den Flügeln und zeigt nach draußen, wo die Sturmgroßdrachen die Rabenbären seines Stammes angreifen.\n\nEs ist offensichtlich, dass er Euch bittet, seinem Schwarm zu helfen.>", sourceObjective = "Tötet 8 tobende Sturmjäger im Sturmgepeitschten Vorgebirge.", completion = "Der Häuptling der Schwarzfedern verneigt sich respektvoll vor Euch.\n\nIhr habt geholfen, das Überleben seines Stammes zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[42447] = { id = 42447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mit dem Rabenbären tanzt", description = "<Der Häuptling fordert die anderen Rabenbären auf, die Tributmaterialien zusammenzutragen, und weist in Richtung des Ritualkreises draußen.>\n\nKrah! Krah-krah!\n\n<Offensichtlich möchte er, dass Ihr ihm folgt.>", sourceObjective = "Helft den Rabenbären der Schwarzfedern, das Tributritual durchzuführen.", completion = "Offensichtlich hatte Nithogg kein Interesse am Tributritual der Rabenbären.\n\nEs ist vermutlich besser, sich aus dem Staub zu machen, bevor er zurückkommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[42449] = { id = 42449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Vier Reiter", description = "Die Stimme des Lichkönigs hat gesprochen, <Todesgebieter/Todesgebieterin>, und die Ritter der Schwarzen Klinge unterwerfen sich Eurem Befehl.\n\nDie Vier Reiter waren keine gewöhnlichen Todesritter, sondern wurden aus purer, unheiliger Macht geboren, die der Lichkönig Kel'Thuzad überlassen hatte.\n\nDiese unheilige Macht, die Toten wiederauferstehen zu lassen, wurde jetzt Euch übertragen, <Todesgebieter/Todesgebieterin>. Ich bin sicher, dass Ihr sie mit großer Entschlossenheit nutzen werdet.\n\nDie Vier Reiter werden wertvolle Verbündete im Kampf gegen die Brennende Legion sein... und Nazgrim ist eine würdige Wahl als Erstgeborener.", sourceObjective = "Sprecht mit Thassarian in Durotar.", completion = "Die Welt der Lebenden wird uns bis in alle Ewigkeit für die finsteren Taten schmähen, die wir heute beginnen...", sourceObjectiveStatus = "unverified-source-field" }
quests[42450] = { id = 42450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brawlgoth" }
quests[42451] = { id = 42451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalecs Plan", description = "Aufgrund der hohen Präsenz der Legion konnte Euer Champion nicht sehr tief in das Arkusgewölbe eindringen. Hoffentlich habt Ihr mehr Erfolg, wenn Ihr Erzmagier Vargoth nach drinnen folgt.\n\nKalecgos wird an der Felsklippe oberhalb der Teufelsseelenbastion auf Euch warten.", sourceObjective = "Trefft Euch mit Kalecgos am Grat nahe dem Arkusgewölbe.", completion = "Schön, Euch wiederzusehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42452] = { id = 42452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Schwarzfrost", description = "Schwarzfrost wurde schon von einer ganzen Reihe mächtiger Kämpfer geführt, die bis zu seinem Erschaffer, Alodi, zurückgeht. Er übergab ihn seinem Lieblingsschüler, der wiederum seinem bis weiter zu... Erzmagier Arrexis, glaube ich.\n\nArrexis ist irgendwann zur Zeit des Ersten Krieges verschwunden. Ich selbst weiß nichts über sein Schicksal, aber die Antworten könnten sich tatsächlich hier in der Bibliothek befinden.\n\nSeht Euch hier mal um. Was immer Ihr findet, kann uns auf die Spur von Schwarzfrost bringen.", sourceObjective = "Untersucht die vergessenen Bücherstapel in der Halle des Wächters, um Hinweise auf Arrexis, den letzten Besitzer von Schwarzfrost, zu finden.", progress = "Und? Haben wir schon, was wir brauchen?", completion = "Aus den Texten, die Ihr gefunden habt, wird deutlich, dass Schwarzfrost jetzt im Besitz von Balaadur ist. Natürlich würde er sich einen solch mächtigen Stab aneignen wollen.\n\nDas ist ein Problem. Aber eines, das wir lösen können. Wir müssen nur irgendwie an Balaadur herankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42453] = { id = 42453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 103 - Medium (RKS)" }
quests[42454] = { id = 42454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer von Khaz'goroth", description = "<Nachdem Ihr Dargrul den Unterkönig nun besiegt habt und den Hammer von Khaz'goroth in den Händen haltet, ist es an der Zeit, ihn in Aegwynns Galerie in den unteren Kammern von Dalaran zu platzieren.>", sourceObjective = "Verwendet den zentralen Teleporter in Dalaran und platziert den Hammer von Khaz'goroth dann in Aegwynns Galerie.", completion = "<Erzmagier Khadgar hat hier einen Platz für den Hammer von Khaz'goroth und den Rest der Säulen der Schöpfung reserviert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42455] = { id = 42455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alodis Edelsteine", description = "Im Gegensatz zu Euch verfügte Arrexis über Heerscharen an Schülern und Helfern für das Ritual.\n\nFrüher, als wir die Magie noch nicht so gut verstanden und große Mengen an Mana für Zauber benötigt haben, haben wir Mana in Edelsteinen gespeichert, um es für komplexe Zauber verwenden zu können.\n\nGlücklicherweise befinden sich in meinem Bankschließfach noch ein paar mächtige Manaedelsteine sowie ein paar andere nützliche Dinge. Ihr müsst einfach nur zur Bank von Dalaran gehen und Euch Zutritt verschaffen.", sourceObjective = "Verschafft Euch Zutritt zu Alodis persönlichem Bankfach in Dalaran und nehmt die Manaedelsteine an Euch.", progress = "Habt Ihr alles in meinem Bankfach gefunden? Ich hoffe, die Sicherheitsmaßnahmen haben Euch keine Unannehmlichkeiten bereitet.", completion = "Ausgezeichnet! Ich bin tatsächlich überrascht, dass ihr {class} keine Manaedelsteine mehr verwendet. Ich fand sie immer sehr hilfreich.\n\nAber auf jeden Fall könnt Ihr damit die fehlenden {class} ausgleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42456] = { id = 42456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assn Rogue - Flavor Event 01 (Horde)" }
