quests[42475] = { id = 42475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 H" }
quests[42476] = { id = 42476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsstandort der Totenwinde", description = "In Eurem Bericht stand etwas von einem Forschungsstandort in der Nähe von Karazhan. Ich hoffe, dort befinden sich noch Materialien, die uns weiterhelfen können.\n\nIhr müsst diesen Ort finden und alles mitbringen, was uns helfen könnte, das Ritual wieder aufleben zu lassen. Und ich werde hier noch etwas weiterforschen.", sourceObjective = "Sucht nach Informationen über das Ritual in Arrexis' Lager nahe Karazhan und bringt sie zurück.", progress = "Ich hoffe, Ihr hattet Erfolg?", completion = "Das ist noch besser, als ich zu hoffen wagte. Ein funktionierender Zauberschutzprototyp und sogar die Ritualnotizen!\n\nLangsam glaube ich, dass es wirklich möglich ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[42477] = { id = 42477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daio der Klapprige", description = "Der Text beschreibt jemanden namens Daio, der extrem wichtig für das Dämonenritual sein soll. Aber dabei handelt es sich doch wohl nicht um Daio den Klapprigen, oder?!\n\nIch wusste gar nicht, dass er zu den Kirin Tor gehörte. Ich kannte ihn nur als ältlichen Hexenmeister, der junge Rekruten in den dämonischen Künsten ausbildete. Aber das würde zumindest erklären, warum er seine Profession gewechselt hat.\n\nEr verfügt vermutlich über wichtige Informationen zu unserem Vorhaben. Er hat sich zwar zurückgezogen, aber ich glaube, er ist immer noch in der Faulenden Narbe in den Verwüsteten Landen. Ihr solltet ihn aufsuchen.", sourceObjective = "Fliegt zur Faulende Narbe in den Verwüsteten Landen, um Informationen von Daio dem Klapprigen zu erhalten.", progress = "Nun? Was hatte Daio zu sagen?", completion = "Unser Orden hat damals einen großen Verlust erlitten. Es ist eine Schande, dass wir die Sache verschwiegen und nicht erforscht haben.\n\nIhr verfügt jetzt über ein weiteres wichtiges Element für das Ritual, und wir sind damit einen Schritt weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[42479] = { id = 42479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Magierjäger", description = "Und damit haben wir alles, was wir brauchen, um das Ritual nachzuvollziehen... wenn auch in eingeschränkter Form. Wir müssen es an einem gut sichtbaren Ort abhalten, damit unser Ziel schnell davon erfährt.\n\nIch hörte, dass die Faronaarregion von Azsuna schwer von der Legion belagert wird. Das ist ein exzellenter Ort, um ein Ritual abzuhalten, das sie keinesfalls zulassen wollen.\n\nUnsere Chancen, dort auf grausame Weise zu sterben, sind außergewöhnlich hoch.", sourceObjective = "Lasst Arrexis' Ritual in Faronaar aufleben und besiegt Balaadur.", completion = "Eure Fähigkeiten erstaunen mich ein ums andere Mal! Balaadur liegt tot im Staub seines eigenen Reiches und Ihr verfügt jetzt über Schwarzfrost. Ich bin gespannt auf Eure nächsten Taten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42480] = { id = 42480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assn Rogue - Flavor Event 02 (Alliance)" }
quests[42481] = { id = 42481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Doom" }
quests[42482] = { id = 42482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assn Rogue - Flavor Event 03" }
quests[42483] = { id = 42483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles auf Hai", description = "So, es bleibt noch eine letzte Bestie, auf die ich Euch ansetzen kann. Sie lebt ein bisschen weit draußen, aber glaubt mir, sie ist es wert. Ich habe nämlich eine ordentliche Summe darauf verwettet!\n\nEntlang der Ostküste patrouilliert ein riesiger Hai, den die Einheimischen Stahlschuppe nennen. Sie behaupten, dass seine Haut fast undurchdringlich sei.\n\nAber Ihr werdet ihnen das Gegenteil beweisen, nicht wahr? Bringt mir seine Flosse, dann werden die Tauren ein hübsches Sümmchen rausrücken müssen.", sourceObjective = "Holt Euch Stahlschuppes Flosse von Stahlschuppe in der Citrinbucht.", completion = "<Die Goblins haben eine Notiz und ein altes Vergrößerungsglas zurücklassen.>\n\nIch wünschte, ich könnte Euren Gesichtsausdruck sehen, aber Raz und ich haben jetzt Besseres zu tun!\n\nDanke für die Trophäen und das Fleisch. Dafür kriegen wir auf dem Schwarzmarkt sicher eine Menge Kohle. Und für all die Waren von den blöden Tauren sowieso! Die brauchen sie ja wohl eh nicht mehr!\n\nBis dann, Dumpfbacke!", sourceObjectiveStatus = "unverified-source-field" }
quests[42484] = { id = 42484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erstgeborene erhebt sich", description = "General Nazgrim war einer der besten Krieger, die unsere Welt je kannte, und seine Treue war beispiellos... selbst für einen Orc.\n\nEr verdient den Frieden des Todes, aber seine Welt schreit nach Rettung. Die Zeit für Ruhe ist vorüber...\n\nKommt, <Todesgebieter/Todesgebieterin>... heißen wir Nazgrim in den Armen der Verdammten willkommen.", sourceObjective = "Lasst Nazgrim als Todesritter wiederauferstehen.", completion = "Gut gemacht, Todesgebieter. Zu Lebzeiten war er einer der größten Generäle der Horde, jetzt dient er Euch als Untoter und Erster Reiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[42485] = { id = 42485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NEU VERWENDEN" }
quests[42486] = { id = 42486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Mama", description = "Ich bin jetzt bereit, nach Hause zu gehen, aber da draußen sind immer noch diese gruseligen Männer...\n\nWerdet Ihr bei mir bleiben und dafür sorgen, dass sie mich nicht holen?\n\nIch will nicht wieder in die Höhle...", sourceObjective = "Bringt Korine zurück zu ihrer Mutter Verene beim Mondsichelforum.", completion = "Oh, meine kleine, süße Korine! Danke! Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[42487] = { id = 42487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde da draußen", description = "Ihr habt viel für uns getan, doch es ist an der Zeit, dass Ihr zu Thalyssra zurückkehrt.\n\nGanz in der Nähe befindet sich eine Teleportationsplattform, die seit einigen Jahren nicht mehr verwendet wird. Versucht doch, ob ihr sie umlenken und so zu Thalyssra zurückkehren könnt.\n\nUnd bevor Ihr Euch auf den Weg macht:\n\n<Vanthir überreicht Euch eine verpackte Flasche Arkwein.>\n\nBringt ihr den mit meinem Dank dafür, dass sie Euch hergeschickt hat. Lasst sie wissen, dass wir dank Eurer Mühen wieder einen Vorrat an Arkwein haben und eine Mutter mit ihrem Kind wiedervereint wurde.\n\nWir sind Euch unendlich dankbar. Lebt wohl.", sourceObjective = "Aktiviert die Teleportationsplattform und überbringt Thalyssra Vanthirs Geschenk.", completion = "Vanthir ist ein sehr freundlicher Geselle.", sourceObjectiveStatus = "unverified-source-field" }
quests[42488] = { id = 42488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalyssras Heimstatt", description = "Während Ihr in der Stadt beschäftigt wart, bin ich bei meinen Nachforschungen über die Verdorrten auf ein Hindernis gestoßen.\n\nIch denke, ich stehe kurz vor einem Durchbruch, doch ohne fortschrittlicheres Werkzeug werde ich nicht weiterkommen.\n\nUnter meinen Besitztümern hielt ich einen Gegenstand verborgen, einen so genannten Arkanverstärker. Er tut genau das, was der Name vermuten lässt.\n\nEs ist sehr wahrscheinlich, dass die Magistrix mein Anwesen inzwischen hat auseinandernehmen lassen. Falls der Verstärker noch dort ist, wird er zu Bruch gegangen sein.\n\nBringt ihn als Ganzes zu mir zurück, wenn es Euch möglich ist.", sourceObjective = "Durchsucht Thalyssras Anwesen und sammelt 3 Verstärkerbruchstücke. Verbindet sie, um einen Arkanverstärker zu erhalten.", progress = "Habt Ihr ihn gefunden?", completion = "Wir haben solch ein Glück, dass er geborgen werden konnte... Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42489] = { id = 42489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalyssras Schubladen", description = "Auf Thalyssras geplündertem Anwesen befinden sich noch jede Menge Dinge, die ihr wichtig sind. Sammelt sie ein und bringt sie ihr.", sourceObjective = "Durchsucht Thalyssras Anwesen und bringt ihr ihre Habseligkeiten.", progress = "Was habt Ihr gefunden?", completion = "Das ist mir ein Trost, für den ich keine Worte finde.", sourceObjectiveStatus = "unverified-source-field" }
quests[42490] = { id = 42490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arkus: Den Arkus öffnen", description = "Tief unter Suramar befinden sich einige stillgelegte Tunnel, die als der Arkus bezeichnet werden. Sie wurden aufgegeben, als eine Katastrophe den Betrieb der dortigen Manasammler in Mitleidenschaft zog.\n\nIch weiß nicht, was Euch dort unten erwartet, doch eins weiß ich.\n\nWir sind nicht die Einzigen, die an diesem Ort interessiert sind. Wenn Ihr genug Lärm macht, wird sicher einer der Berater erscheinen, an deren Seite ich Elisande diente.\n\nEr heißt Vandros. Tötet ihn, wenn Ihr könnt.\n\nSein Tod wird ein Triumph für uns sein, denn damit berauben wir Elisande um eine der Waffen aus ihrem Arsenal.", sourceObjective = "Tötet Berater Vandros im Arkus.", completion = "Ich danke Euch. Eine Sache weniger, über die ich mir Gedanken machen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[42491] = { id = 42491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arkus: Lang begrabenes Wissen", description = "Unterhalb von Suramar gibt es ein uraltes Netzwerk von Tunneln, das wir den Arkus nennen.\n\nDie Tunnel wurden vor einiger Zeit verlassen, als Teile der Höhle einzustürzen drohten. Niemand weiß, was seitdem dort unten geschieht.\n\nAber unabhängig davon, was sich dort unten noch so befindet, gibt es dort etwas, das uns langfristig den Erfolg sichern kann, wie ich glaube.\n\nVor langer Zeit hat mein Volk alle Leylinien in und um Suramar herum kartografiert. Diese Aufzeichnungen müssten sich noch immer in der Bibliothek des Arkus befinden.\n\nBitte sucht für mich nach dieser Karte.", sourceObjective = "Besorgt die Leylinienkarte von Suramar aus dem Arkus.", progress = "Habt Ihr sie gefunden?", completion = "Ausgezeichnet! Ich werde sie mir gleich ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42493] = { id = 42493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist der Untergaaaaaaang!", description = "Millhaus zieht Ärger magisch an. Wenn Erzmagier Vargoth also noch hier ist, wird er ihn mit Sicherheit finden.\n\nOh, und wenn Ihr den Seelenstein der Nachtgeborenen findet, solltet Ihr ihn Euch zuerst schnappen!", sourceObjective = "Untersucht das Gewölbe der Nachtgeborenen.", completion = "Dann ist es also wahr. Erzmagier Vargoth wurde durch die Legion verderbt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42494] = { id = 42494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essen für alle", description = "Eure Champions haben bei der Dezimierung der Feinde gute Arbeit geleistet. Zudem haben sie eine Reihe fast verhungerter Gefangener gefunden, die unsere Hilfe brauchen. Mithilfe Eures herbeigezauberten Manapuddings oder Eurer Manapuffer könnten wir sie wieder auf die Beine kriegen.\n\nUnd Ihr solltet so viele der verbleibenden Legionsinvasoren wie möglich zurück in den Wirbelnden Nether schicken!", sourceObjective = "Löscht 15 Dämonen aus und gebt 10 fast verhungerten Gefangenen Eure herbeigezauberten Lebensmittel.", completion = "Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42495] = { id = 42495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashbringer Chosen" }
quests[42496] = { id = 42496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truthguard Chosen" }
quests[42497] = { id = 42497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Hand Chosen" }
quests[42501] = { id = 42501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unvollendete Aufgabe", description = "Garona ist vor einiger Zeit losgezogen, um die Anführer eines Legionskultes auszuschalten. Seitdem haben wir nichts mehr von ihr gehört.\n\nUnd was noch schlimmer ist: Sie hat die Königsmörder mitgenommen. Dabei weiß sie selbst, dass sie die dunkelsten Seiten in ihr hervorbringen!\n\nWenn Ihr ihre Arbeit fortsetzt, solltet Ihr Garona am ehesten finden können. Unseren Informationen zufolge bildet ein Hexenmeister namens Caden Schattenblick am Altar der Stürme in den Verwüsteten Landen neue Rekruten aus. Seht nach, ob sich in seinen Taschen etwas Verwertbares finden lässt.\n\nNachdem er tot ist, meine ich.", sourceObjective = "Liquidiert Caden Schattenblick am Altar der Stürme in den Verwüsteten Landen und durchsucht seine Leiche nach Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42502] = { id = 42502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zuflucht", description = "Wir haben noch einen weiteren, möglicherweise wertvollen Hinweis. Ein Elitemitglied des Kults namens Teufelsrufer Whitley konnte unseren Agenten schon mehrmals entkommen.\n\nLaut neuesten Informationen soll er sich jetzt in Rabenflucht im Dämmerwald aufhalten. Er verfügt ganz sicher über wichtige Informationen für Eure Suche.\n\nIhr wisst ja, was jetzt zu tun ist.", sourceObjective = "Liquidiert Teufelsrufer Whitley in Rabenflucht im Dämmerwald und durchsucht seine Leiche nach Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42503] = { id = 42503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Codeknacker", description = "<Die verschlüsselte Nachricht, die Ihr gefunden habt, wird von mächtiger Magie geschützt und ist mit konventionellen Methoden nicht zu entschlüsseln.>\n\n<Mit dem Codeschlüssel von Teufelsrufer Whitley könnt Ihr den Code vielleicht knacken. Damit seid Ihr der Operationsbasis des Kultes und Garona einen Schritt näher.>", sourceObjective = "Nutzt den dämonischen Codeschlüssel, um die verschlüsselte Nachricht lesbar zu machen und weitere Hinweise auf den nächsten Aufenthaltsort der Kultisten zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42504] = { id = 42504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ungesehene Klinge", description = "Wir dürfen Sturmwind auf keinen Fall in die Hände der Legion fallen lassen. Und ich traue Shaw oder seinen SI:7-Schergen nicht zu, die Hand alleine in den Griff zu bekommen.\n\nWir zwei werden uns darum kümmern müssen, solange noch Zeit ist.\n\nDie gesamte Stadt ist bereits nervös wegen der Gerüchte über die Aktivitäten des Kultes. Wenn Ihr nicht aufpasst, wird man dort genauso schnell auf Euch losgehen wie auf die Kultisten.\n\nDie anderen Schatten haben in den höchsten Tönen von Euren Fertigkeiten gesprochen. Seid Ihr dabei?", sourceObjective = "Helft Garona, die Kultisten der Verschleierten Hand in Sturmwind auszuschalten.", completion = "Jeder Augenblick, den ich diese Klingen hielt, war die reinste Qual. Sie gehören ganz Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42505] = { id = 42505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcanist Shal'iman" }
quests[42506] = { id = 42506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folianten alter Zeiten" }
quests[42507] = { id = 42507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assn Rogue - Flavor Event 04" }
quests[42508] = { id = 42508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein zahnloser Drache", description = "Das Arkusgewölbe lag über Tausende von Jahren begraben und unentdeckt. Wir haben es der Legion zu verdanken, dass es wieder zugänglich ist. Allerdings wäre es mir lieber gewesen, wenn es verborgen geblieben wäre.\n\nIch glaube, dass wir Erzmagier Vargoth dicht auf den Fersen sind und er schon im Gewölbe sein könnte. Wir müssen uns beeilen, wenn wir ihn einholen wollen.", sourceObjective = "Reitet mit Kalecgos zum Arkusgewölbe.", completion = "Ich werde sie draußen beschäftigen, während Ihr hineingeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42509] = { id = 42509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42510] = { id = 42510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsterbliche Seele", description = "Illidans unsterbliche Dämonenseele irrt irgendwo durch die Weiten des Wirbelnden Nethers. Es ist sehr riskant, mit ihm Verbindung aufzunehmen, denn der Nether ist voller unglaublich mächtiger Kreaturen mit unsäglichen Begierden. Doch das müssen wir auf uns nehmen, wenn wir Fortschritte machen wollen.\n\nDas Ritual kann mithilfe des Nethertiegels durchgeführt werden. Bringt das Blutopfer dar, {name}.", sourceObjective = "Bringt zum Abschluss des Rituals das Blutopfer dar und nehmt mit der Seele von Illidan Sturmgrimm Verbindung auf.", progress = "Jetzt muss nur noch das Blutopfer dargebracht werden. Dann werden wir sehen, was die Zukunft den Illidari bringen wird.", completion = "Wir müssen uns vorbereiten. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[42511] = { id = 42511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzerrte Seelen" }
quests[42512] = { id = 42512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Hochbergs", description = "Das muss genügen. Dargrul ist eingetroffen und wir benötigen jeden verfügbaren Tauglichen an der Frontlinie. Geht Ihr voran, ich werde dichtauf folgen.", sourceObjective = "Besiegt Dargrul.", completion = "Das Dorf. Es... es ist... einfach nicht mehr da. Man hat mir berichtet, was an der Flusswindung passiert ist, aber ich hielt es für eine Übertreibung.", sourceObjectiveStatus = "unverified-source-field" }
quests[42513] = { id = 42513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashamane's Fall" }
quests[42516] = { id = 42516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsende Macht", description = "Erzdruide Rensar Großhuf wünscht, Euch zu sehen.\n\nUnsere Kampagne zur Verteidigung der Verheerten Inseln ist angelaufen und wir benötigen Eure leitende Hand.", sourceObjective = "Sprecht mit Rensar Großhuf im Hain der Träume.", completion = "Gut! Wie ich sehe, habt Ihr an Macht hinzugewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42517] = { id = 42517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual der Verdammnis", description = "Eure Nachforschungen haben Euch Zugang zu einem sehr mächtigen Ritual verschafft. Aber wenn Ihr damit einen Dämon beschwören wollt, braucht Ihr die Hilfe einiger Eurer Freunde.\n\nDas Ritual muss oben auf der Beschwörungsplattform durchgeführt werden.\n\nVergesst nicht, dass man für diese Art von Macht stets einen Preis bezahlt. Nicht alle, die an dem Ritual teilnehmen, werden auch überleben. Bereitet Euch gut vor.", sourceObjective = "Führt das Ritual der Verdammnis auf der Beschwörungsplattform in der Schreckensnarbe durch.", completion = "Es ist also alles gut gelaufen?\n\nEin Ritual von solcher Größe ist ziemlich anstrengend. Mehr als einmal pro Tag könnte das niemand aushalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42519] = { id = 42519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "In Eurer Eigenschaft als <Anführer/Anführerin> des Ordens werden sich andere Jäger ratsuchend an Euch wenden. Viele werden Euch Treue schwören und alles Notwendige im Namen des Unsichtbaren Pfads tun.\n\nIch kenne zwei von uns, die von dem, was sie bisher von Euch gesehen haben, zutiefst beeindruckt sind und auf jede erdenkliche Weise helfen wollen.\n\nSucht sie auf, damit sie Euch die Bürde der Führung erleichtern.", sourceObjective = "Rekrutiert Emmarel Schattenwächter und Loren Sturmhuf.", completion = "Hervorragend. Emmarel Schattenwächter und Loren Sturmhuf sind würdige Champions. Wir können darauf bauen, dass sie alle ihnen aufgetragenen Aufgaben ausführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42520] = { id = 42520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein furchtbarer Verlust", description = "Ich könnte behaupten, dass mich diese furchtbare Wendung der Ereignisse überrascht, aber in letzter Zeit überrascht mich gar nichts mehr. Es sind finstere Zeiten und selbst die Aufrichtigsten unter uns können der Versuchung erliegen...\n\nWir sollten umgehend Erzmagier Khadgar von Vargoths Verrat berichten.", sourceObjective = "Kehrt zur Halle des Wächters zurück.", completion = "Der Verlust von Erzmagier Vargoth ist furchtbar für unseren Orden, {name}. Es sind wirklich finstere Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42521] = { id = 42521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes...", description = "Millhaus Manasturm hat lautstark verkündet, dass er den Seelenstein der Nachtgeborenen in seinen Besitz bringen will. Vielleicht könnt Ihr den Gnom ja für Eure eigenen Zwecke einspannen, wenn Ihr ihn findet.\n\nAllerdings ist er mitunter sehr unberechenbar. Nehmt Euch also in seiner Nähe in acht, {name}. Verwendet meinen Kristall, um mich zu kontaktieren, sobald Ihr ihn ausfindig gemacht habt.", sourceObjective = "Findet Millhaus Manasturm.", progress = "Habt Ihr Millhaus finden können?", completion = "Ich hoffe, dass Ihr Millhaus' Entschlossenheit für Eure eigenen Zwecke nutzen könnt!", sourceObjectiveStatus = "unverified-source-field" }
